import { ReplayTrace } from '../chronology/replay-compressor.js';

export interface Hypothesis {
    label: string;
    description: string;
    probability: number; // 0.0 to 1.0
    confidenceInterval: [number, number]; // [min, max]
    supportingEvidence: string[];
}

export interface ProbabilisticReport {
    traceId: string;
    primaryRootCause: string;
    hypotheses: Hypothesis[];
    chronologicalAnomaliesCount: number;
}

export class ProbabilisticExplainabilityEngine {
    /**
     * Examines trace steps to generate competing hypotheses with uncertainty weights.
     */
    public generateHypotheses(trace: ReplayTrace): ProbabilisticReport {
        const hypotheses: Hypothesis[] = [];
        let chronologicalAnomaliesCount = 0;

        if (trace.steps.length === 0) {
            return {
                traceId: trace.traceId,
                primaryRootCause: 'UNKNOWN_EMPTY_TRACE',
                hypotheses: [{
                    label: 'NO_DATA',
                    description: 'The trace does not contain any execution steps.',
                    probability: 1.0,
                    confidenceInterval: [1.0, 1.0],
                    supportingEvidence: ['Trace step array length is 0.']
                }],
                chronologicalAnomaliesCount: 0
            };
        }

        const clockEvidence: string[] = [];
        const gapEvidence: string[] = [];
        const contentionEvidence: string[] = [];

        let prevStep: typeof trace.steps[0] | null = null;
        const actionCounts = new Map<string, number>();

        for (const step of trace.steps) {
            actionCounts.set(step.action, (actionCounts.get(step.action) || 0) + 1);

            if (prevStep) {
                const timeDelta = step.timestamp - prevStep.timestamp;
                const indexDelta = step.index - prevStep.index;

                // 1. Clock skew / temporal inversion checks
                if (timeDelta < 0) {
                    chronologicalAnomaliesCount++;
                    clockEvidence.push(`Step ${step.index} has a timestamp (${step.timestamp}) preceding step ${prevStep.index} (${prevStep.timestamp}) by ${Math.abs(timeDelta)}ms.`);
                }

                // 2. Missing data log checks
                if (indexDelta > 1) {
                    chronologicalAnomaliesCount++;
                    gapEvidence.push(`Step index discontinuity: skipped index from ${prevStep.index} to ${step.index} (${indexDelta - 1} unlogged steps).`);
                }
            }
            prevStep = step;
        }

        // 3. Resource/Lease contention checks
        for (const [action, count] of actionCounts.entries()) {
            if (count > 2 && (action.includes('LEASE') || action.includes('ACQUIRE') || action.includes('LOCK'))) {
                contentionEvidence.push(`High frequency concurrency loop detected for action [${action}]: executed ${count} times.`);
            }
        }

        // Formulate Hypotheses with weight parameters
        let rawClockWeight = clockEvidence.length > 0 ? (0.6 + clockEvidence.length * 0.1) : 0.05;
        let rawGapWeight = gapEvidence.length > 0 ? (0.5 + gapEvidence.length * 0.1) : 0.05;
        let rawContentionWeight = contentionEvidence.length > 0 ? (0.4 + contentionEvidence.length * 0.1) : 0.05;

        // Default baseline weight if no errors exist
        if (clockEvidence.length === 0 && gapEvidence.length === 0 && contentionEvidence.length === 0) {
            hypotheses.push({
                label: 'DETERMINISTIC_COHERENCE',
                description: 'The execution trace follows expected chronological steps with zero anomalies.',
                probability: 0.90,
                confidenceInterval: [0.85, 0.95],
                supportingEvidence: ['All sequence indices are contiguous.', 'Monotonic clock timestamps verified.']
            });
            hypotheses.push({
                label: 'UNDETECTED_STATE_DRIFT',
                description: 'Minor silent drift could exist without triggering structural anomalies.',
                probability: 0.10,
                confidenceInterval: [0.05, 0.15],
                supportingEvidence: ['Lack of explicit drift assertions.']
            });
        } else {
            // Normalize weights so they sum to 1.0
            const totalWeight = rawClockWeight + rawGapWeight + rawContentionWeight;

            if (clockEvidence.length > 0) {
                const prob = Math.round((rawClockWeight / totalWeight) * 100) / 100;
                hypotheses.push({
                    label: 'CLOCK_SKEW_OR_VM_DISCONTINUITY',
                    description: 'Low-level hypervisor suspension pause or NTP timing correction step-change.',
                    probability: prob,
                    confidenceInterval: [Math.max(0, prob - 0.1), Math.min(1.0, prob + 0.1)],
                    supportingEvidence: clockEvidence
                });
            }

            if (gapEvidence.length > 0) {
                const prob = Math.round((rawGapWeight / totalWeight) * 100) / 100;
                hypotheses.push({
                    label: 'TELEMETRY_LOG_LOSS_OR_BUFFER_EXHAUSTION',
                    description: 'Network buffer overflow or write-queue drop discarding chronology logs.',
                    probability: prob,
                    confidenceInterval: [Math.max(0, prob - 0.12), Math.min(1.0, prob + 0.12)],
                    supportingEvidence: gapEvidence
                });
            }

            if (contentionEvidence.length > 0) {
                const prob = Math.round((rawContentionWeight / totalWeight) * 100) / 100;
                hypotheses.push({
                    label: 'CONCURRENT_LEASE_ACQUISITION_RACE',
                    description: 'Distributed split-brain contention trying to secure primary node ownership.',
                    probability: prob,
                    confidenceInterval: [Math.max(0, prob - 0.08), Math.min(1.0, prob + 0.08)],
                    supportingEvidence: contentionEvidence
                });
            }

            // Sort hypotheses by probability descending
            hypotheses.sort((a, b) => b.probability - a.probability);

            // Adjust last element slightly to ensure total sums to exactly 1.0 due to rounding
            const sum = hypotheses.reduce((acc, h) => acc + h.probability, 0);
            if (sum !== 1.0 && hypotheses.length > 0) {
                hypotheses[0].probability = Math.round((hypotheses[0].probability + (1.0 - sum)) * 100) / 100;
            }
        }

        const primaryRootCause = hypotheses.length > 0 ? hypotheses[0].label : 'UNKNOWN';

        return {
            traceId: trace.traceId,
            primaryRootCause,
            hypotheses,
            chronologicalAnomaliesCount
        };
    }
}

export interface OperatorRationale {
    overrideId: string;
    rationale: string;
    operatorName: string;
    timestamp: number;
    playbookLineage: string;
    decisionProvenance: string;
    overrideRationale: string;
    abandonedTelemetryAncestry: string[];
    context: Record<string, any>;
}

export interface DecisionRecord {
    decisionId: string;
    operatorName: string;
    timestamp: number;
    chosenHypothesis: string;
    alternativeHypotheses: string[];
    actualOutcomeRootCause: string; // The true cause discovered later
    confidenceLevel: 'LOW' | 'MEDIUM' | 'HIGH';
}

export interface HypothesisDecayReport {
    totalDecisionsAudited: number;
    wrongPathwaysCount: number;
    accuracyRate: number;
    wrongPathwaysDetail: Array<{ chosen: string; actual: string; count: number }>;
    operatorTrustAudit: Record<string, { totalDecisions: number; overTrustedCount: number; trustScore: number }>;
    recurringBiasPatterns: string[];
}

export interface ResurrectedRecord {
    resurrectionId: string;
    subsystemName: string;
    operatorName: string;
    timestamp: number;
    requestContext: {
        restorationReason: string;
        expectedBlastRadius: 'LOW' | 'MEDIUM' | 'HIGH';
        survivabilityCategory: 'catastrophic' | 'operational' | 'convenience';
        reRetirementCondition: string;
        telemetryDeltaEstimate: number; // 0.0 to 1.0
        rollbackPlan: string;
        sunsetDays: number;
        coSignatures?: string[];
    };
}

export interface ActualResurrectionOutcome {
    resurrectionId: string;
    actualBlastRadius: 'LOW' | 'MEDIUM' | 'HIGH';
    actualTelemetryDelta: number; // 0.0 to 1.0
    actualMaintenanceBurden: number;
    actualSurvivabilityGain: 'HIGH' | 'MEDIUM' | 'LOW' | 'NONE';
}

export interface GroupConsensusBiasReport {
    consensusOptimismDetected: boolean;
    groupResurrectionBiasScore: number; // proportion of total forecasts that were underestimations
    correlatedForecastingFailures: Array<{
        subsystemName: string;
        operatorsInvolved: string[];
        underestimatedFields: string[];
        severityScore: number; // 0 to 1 based on severity of combined underestimations
        contagionIndex: number;
    }>;
    temporalClusteringDetected: boolean;
    confidenceContagionFactor: number;
}

export interface ResurrectionAuditReport {
    totalAudited: number;
    underestimatedBlastRadiusCount: number;
    underestimatedTelemetryDeltaCount: number;
    averagePredictionAccuracy: number; // 0.0 to 1.0
    operatorAccuracyScores: Record<string, {
        totalResurrections: number;
        accuracyScore: number; // 0.0 to 1.0
        optimismBiasDetected: boolean;
    }>;
    groupConsensusBias?: GroupConsensusBiasReport;
    warnings: string[];
}

export class StewardshipMemoryPreservator {
    private rationales = new Map<string, OperatorRationale>();
    private operatorSeniorities = new Map<string, 'JUNIOR' | 'SENIOR' | 'LEAD'>();

    // Internal lists for automated forgetting/compaction
    private historicalDecisionsList: DecisionRecord[] = [];
    private resurrectionRecordsList: ResurrectedRecord[] = [];
    private resurrectionOutcomesList: ActualResurrectionOutcome[] = [];

    // Compacted base states
    private compactedDecisionsCount = 0;
    private compactedWrongPathwaysCount = 0;
    private compactedResurrectionsCount = 0;
    private compactedUnderestimatedBlastRadiusCount = 0;
    private compactedUnderestimatedTelemetryCount = 0;
    private compactedAccuracySum = 0;

    /**
     * Registers an operator's seniority role to weight forecasting models.
     */
    public registerOperatorSeniority(name: string, role: 'JUNIOR' | 'SENIOR' | 'LEAD'): void {
        this.operatorSeniorities.set(name, role);
    }

    /**
     * Returns an operator's registered seniority or defaults to JUNIOR.
     */
    public getOperatorSeniority(name: string): 'JUNIOR' | 'SENIOR' | 'LEAD' {
        return this.operatorSeniorities.get(name) || 'JUNIOR';
    }

    /**
     * Records a decision record to the internal history list.
     */
    public addDecisionRecord(record: DecisionRecord): void {
        this.historicalDecisionsList.push(record);
    }

    /**
     * Records a resurrection event and optional outcomes to the internal history list.
     */
    public addResurrectionRecord(record: ResurrectedRecord, outcome?: ActualResurrectionOutcome): void {
        this.resurrectionRecordsList.push(record);
        if (outcome) {
            this.resurrectionOutcomesList.push(outcome);
        }
    }

    /**
     * Saves operator reasoning, playbook lineage, and decision context.
     */
    public recordOperatorRationale(rationale: OperatorRationale): void {
        this.rationales.set(rationale.overrideId, rationale);
    }

    /**
     * Retrieves stored operator rationale.
     */
    public getOperatorRationale(overrideId: string): OperatorRationale | undefined {
        return this.rationales.get(overrideId);
    }

    /**
     * Compacts/anonymizes history records older than maxAgeMs to prevent database bloat,
     * maintaining base statistics while forgetting specific SRE names and playbooks.
     */
    public forgetStaleHistory(maxAgeMs: number): void {
        const currentTime = Date.now();
        const cutoff = currentTime - maxAgeMs;

        // 1. Compact Decisions
        const activeDecisions: DecisionRecord[] = [];
        for (const decision of this.historicalDecisionsList) {
            if (decision.timestamp < cutoff) {
                this.compactedDecisionsCount++;
                const isCorrect = decision.chosenHypothesis === decision.actualOutcomeRootCause;
                if (!isCorrect) {
                    this.compactedWrongPathwaysCount++;
                }
            } else {
                activeDecisions.push(decision);
            }
        }
        this.historicalDecisionsList = activeDecisions;

        // 2. Compact Resurrections
        const outcomesMap = new Map<string, ActualResurrectionOutcome>();
        this.resurrectionOutcomesList.forEach(o => outcomesMap.set(o.resurrectionId, o));

        const activeResurrections: ResurrectedRecord[] = [];
        const activeOutcomes: ActualResurrectionOutcome[] = [];

        const blastRadiusVal = { 'LOW': 1, 'MEDIUM': 2, 'HIGH': 3 };

        for (const res of this.resurrectionRecordsList) {
            if (res.timestamp < cutoff) {
                this.compactedResurrectionsCount++;
                const outcome = outcomesMap.get(res.resurrectionId);
                if (outcome) {
                    const predRadius = blastRadiusVal[res.requestContext.expectedBlastRadius];
                    const actualRadius = blastRadiusVal[outcome.actualBlastRadius];

                    if (predRadius < actualRadius) {
                        this.compactedUnderestimatedBlastRadiusCount++;
                    }
                    if (res.requestContext.telemetryDeltaEstimate < outcome.actualTelemetryDelta) {
                        this.compactedUnderestimatedTelemetryCount++;
                    }

                    const telemetryAccuracy = 1 - Math.abs(res.requestContext.telemetryDeltaEstimate - outcome.actualTelemetryDelta);
                    const radiusAccuracy = 1 - Math.abs(predRadius - actualRadius) / 2;
                    this.compactedAccuracySum += (telemetryAccuracy + radiusAccuracy) / 2;
                    activeOutcomes.push(outcome); // Keep for reference or let activeOutcomes prune if outcome wasn't matched
                } else {
                    this.compactedAccuracySum += 1.0; // default ideal accuracy if no outcome available
                }
            } else {
                activeResurrections.push(res);
                const outcome = outcomesMap.get(res.resurrectionId);
                if (outcome) {
                    activeOutcomes.push(outcome);
                }
            }
        }
        this.resurrectionRecordsList = activeResurrections;
        this.resurrectionOutcomesList = activeOutcomes;
    }

    /**
     * Audits which diagnostic pathways were historically wrong, which operators over-trusted
     * certain narratives, and identifies recurring diagnostic bias patterns.
     */
    public auditHypothesisDecay(historicalDecisions?: DecisionRecord[]): HypothesisDecayReport {
        const decisionsToUse = historicalDecisions || this.historicalDecisionsList;
        const totalDecisionsAudited = decisionsToUse.length + this.compactedDecisionsCount;

        if (totalDecisionsAudited === 0) {
            return {
                totalDecisionsAudited: 0,
                wrongPathwaysCount: 0,
                accuracyRate: 1.0,
                wrongPathwaysDetail: [],
                operatorTrustAudit: {},
                recurringBiasPatterns: ['No historical decisions to analyze.']
            };
        }

        let wrongPathwaysCount = this.compactedWrongPathwaysCount;
        const pathwaysMap = new Map<string, number>();
        const operatorMap = new Map<string, { total: number; overTrusted: number }>();

        for (const decision of decisionsToUse) {
            const isCorrect = decision.chosenHypothesis === decision.actualOutcomeRootCause;

            // Track operator trust
            const opData = operatorMap.get(decision.operatorName) || { total: 0, overTrusted: 0 };
            opData.total++;

            if (!isCorrect) {
                wrongPathwaysCount++;
                const pathKey = `${decision.chosenHypothesis}->${decision.actualOutcomeRootCause}`;
                pathwaysMap.set(pathKey, (pathwaysMap.get(pathKey) || 0) + 1);

                // If chosen hypothesis was wrong but operator confidence was HIGH, mark as over-trusted
                if (decision.confidenceLevel === 'HIGH') {
                    opData.overTrusted++;
                }
            }

            operatorMap.set(decision.operatorName, opData);
        }

        const wrongPathwaysDetail: Array<{ chosen: string; actual: string; count: number }> = [];
        for (const [key, count] of pathwaysMap.entries()) {
            const [chosen, actual] = key.split('->');
            wrongPathwaysDetail.push({ chosen, actual, count });
        }

        const operatorTrustAudit: Record<string, { totalDecisions: number; overTrustedCount: number; trustScore: number }> = {};
        for (const [opName, data] of operatorMap.entries()) {
            const trustScore = data.total > 0 ? (data.total - data.overTrusted) / data.total : 1.0;
            operatorTrustAudit[opName] = {
                totalDecisions: data.total,
                overTrustedCount: data.overTrusted,
                trustScore: Math.round(trustScore * 100) / 100
            };
        }

        // Identify recurring bias patterns
        const recurringBiasPatterns: string[] = [];

        // 1. Check for Confirmation/Availability Bias: choosing the same wrong hypothesis repeatedly
        const wrongHypothesisCounts = new Map<string, number>();
        for (const detail of wrongPathwaysDetail) {
            wrongHypothesisCounts.set(detail.chosen, (wrongHypothesisCounts.get(detail.chosen) || 0) + detail.count);
        }
        for (const [chosen, count] of wrongHypothesisCounts.entries()) {
            if (count >= 3) {
                recurringBiasPatterns.push(`Confirmation Bias: Hypothesis '${chosen}' was incorrectly chosen as the root cause ${count} times.`);
            }
        }

        // 2. Check for Overconfidence Bias: operator trustScore is low
        for (const [opName, audit] of Object.entries(operatorTrustAudit)) {
            if (audit.overTrustedCount >= 2 && audit.trustScore < 0.70) {
                recurringBiasPatterns.push(`Overconfidence Bias: Operator '${opName}' consistently shows high confidence on incorrect diagnostics (${audit.overTrustedCount} over-trusted errors).`);
            }
        }

        if (recurringBiasPatterns.length === 0 && wrongPathwaysCount > 0) {
            recurringBiasPatterns.push('No dominant bias patterns detected, but general diagnostic deviations exist.');
        } else if (wrongPathwaysCount === 0) {
            recurringBiasPatterns.push('No bias patterns detected. Diagnostic accuracy is at 100%.');
        }

        const accuracyRate = Math.round(((totalDecisionsAudited - wrongPathwaysCount) / totalDecisionsAudited) * 100) / 100;

        return {
            totalDecisionsAudited,
            wrongPathwaysCount,
            accuracyRate,
            wrongPathwaysDetail,
            operatorTrustAudit,
            recurringBiasPatterns
        };
    }

    /**
     * Audits resurrection predictions against actual outcome metrics.
     * Maps blast radius estimates and telemetry estimates to compute operator forecasting accuracy,
     * accounting for authority seniority, temporal incident clustering, and review confidence contagion.
     */
    public auditResurrectionPredictions(
        resurrections?: ResurrectedRecord[],
        outcomes?: ActualResurrectionOutcome[]
    ): ResurrectionAuditReport {
        const resToUse = resurrections || this.resurrectionRecordsList;
        const outToUse = outcomes || this.resurrectionOutcomesList;

        const totalAudited = resToUse.length + this.compactedResurrectionsCount;
        if (totalAudited === 0) {
            return {
                totalAudited: 0,
                underestimatedBlastRadiusCount: 0,
                underestimatedTelemetryDeltaCount: 0,
                averagePredictionAccuracy: 1.0,
                operatorAccuracyScores: {},
                warnings: ['No resurrection prediction records available to audit.']
            };
        }

        const outcomesMap = new Map<string, ActualResurrectionOutcome>();
        outToUse.forEach(o => outcomesMap.set(o.resurrectionId, o));

        let underestimatedBlastRadiusCount = this.compactedUnderestimatedBlastRadiusCount;
        let underestimatedTelemetryDeltaCount = this.compactedUnderestimatedTelemetryCount;
        let totalAccuracySum = this.compactedAccuracySum;

        const operatorMap = new Map<string, { total: number; sumAccuracy: number; underestimateCount: number }>();
        const blastRadiusVal = { 'LOW': 1, 'MEDIUM': 2, 'HIGH': 3 };

        // Group by subsystem for correlated failure analysis
        const subsystemGroup = new Map<string, Array<{ res: ResurrectedRecord; outcome: ActualResurrectionOutcome }>>();

        // Multipliers for authority weighting
        const seniorityWeights = { 'JUNIOR': 1.0, 'SENIOR': 1.5, 'LEAD': 2.0 };

        // For temporal clustering tracking
        const underestimationTimestamps: number[] = [];

        // For confidence contagion tracking
        let coSignedUnderestimations = 0;

        for (const res of resToUse) {
            const outcome = outcomesMap.get(res.resurrectionId);
            if (!outcome) continue;

            const predRadius = blastRadiusVal[res.requestContext.expectedBlastRadius];
            const actualRadius = blastRadiusVal[outcome.actualBlastRadius];

            let underestimatedRadius = false;
            if (predRadius < actualRadius) {
                underestimatedBlastRadiusCount++;
                underestimatedRadius = true;
            }

            let underestimatedTelemetry = false;
            if (res.requestContext.telemetryDeltaEstimate < outcome.actualTelemetryDelta) {
                underestimatedTelemetryDeltaCount++;
                underestimatedTelemetry = true;
            }

            // Accuracy metrics (0.0 to 1.0)
            const telemetryAccuracy = 1 - Math.abs(res.requestContext.telemetryDeltaEstimate - outcome.actualTelemetryDelta);
            const radiusAccuracy = 1 - Math.abs(predRadius - actualRadius) / 2;
            const singleAccuracy = (telemetryAccuracy + radiusAccuracy) / 2;

            totalAccuracySum += singleAccuracy;

            const opName = res.operatorName;
            const opData = operatorMap.get(opName) || { total: 0, sumAccuracy: 0, underestimateCount: 0 };
            opData.total++;
            opData.sumAccuracy += singleAccuracy;
            if (underestimatedRadius || underestimatedTelemetry) {
                opData.underestimateCount++;
                underestimationTimestamps.push(res.timestamp);
                if (res.requestContext.coSignatures && res.requestContext.coSignatures.length > 0) {
                    coSignedUnderestimations++;
                }
            }
            operatorMap.set(opName, opData);

            // Add to subsystem grouping
            const list = subsystemGroup.get(res.subsystemName) || [];
            list.push({ res, outcome });
            subsystemGroup.set(res.subsystemName, list);
        }

        const averagePredictionAccuracy = totalAccuracySum / totalAudited;
        const operatorAccuracyScores: Record<string, { totalResurrections: number; accuracyScore: number; optimismBiasDetected: boolean }> = {};
        const warnings: string[] = [];

        for (const [opName, data] of operatorMap.entries()) {
            const accuracyScore = data.sumAccuracy / data.total;
            const optimismBiasDetected = (data.underestimateCount / data.total > 0.50) && (accuracyScore < 0.80);

            operatorAccuracyScores[opName] = {
                totalResurrections: data.total,
                accuracyScore: Math.round(accuracyScore * 100) / 100,
                optimismBiasDetected
            };

            if (optimismBiasDetected) {
                warnings.push(`Forecasting Optimism Bias detected for operator '${opName}': consistently underestimating complexity or blast radius of resurrected subsystems.`);
            }
        }

        // --- Advanced Group Consensus Bias Auditing & Correlated Failure Analysis ---
        const correlatedForecastingFailures: Array<{
            subsystemName: string;
            operatorsInvolved: string[];
            underestimatedFields: string[];
            severityScore: number;
            contagionIndex: number;
        }> = [];

        let totalWeightedErrors = 0;
        let totalWeightedPossible = 0;

        for (const [subsystemName, items] of subsystemGroup.entries()) {
            const operatorsSet = new Set<string>();
            const fieldsSet = new Set<string>();
            let errorSum = 0;
            let underestimationsCount = 0;
            let coSignerWeightFactor = 0;

            for (const { res, outcome } of items) {
                const predRadius = blastRadiusVal[res.requestContext.expectedBlastRadius];
                const actualRadius = blastRadiusVal[outcome.actualBlastRadius];

                const opRole = this.getOperatorSeniority(res.operatorName);
                const M_op = seniorityWeights[opRole];

                let isUnderestimated = false;

                if (predRadius < actualRadius) {
                    fieldsSet.add('blastRadius');
                    const error = (actualRadius - predRadius) / 2;
                    errorSum += error;
                    totalWeightedErrors += error * M_op;
                    isUnderestimated = true;
                }
                if (res.requestContext.telemetryDeltaEstimate < outcome.actualTelemetryDelta) {
                    fieldsSet.add('telemetryDelta');
                    const error = (outcome.actualTelemetryDelta - res.requestContext.telemetryDeltaEstimate);
                    errorSum += error;
                    totalWeightedErrors += error * M_op;
                    isUnderestimated = true;
                }

                totalWeightedPossible += 2 * M_op;

                if (isUnderestimated) {
                    operatorsSet.add(res.operatorName);
                    underestimationsCount++;

                    // Track co-signatures confidence propagation
                    if (res.requestContext.coSignatures) {
                        for (const cosigner of res.requestContext.coSignatures) {
                            const cosignerRole = this.getOperatorSeniority(cosigner);
                            coSignerWeightFactor += seniorityWeights[cosignerRole];
                        }
                    }
                }
            }

            // Correlated forecasting failure occurs if multiple events occur or multiple operators make errors
            if (underestimationsCount > 0 && (operatorsSet.size >= 2 || items.length >= 2)) {
                const severityScore = Math.min(1.0, errorSum / (items.length * 2));
                const contagionIndex = 1.0 + (coSignerWeightFactor * 0.25);

                correlatedForecastingFailures.push({
                    subsystemName,
                    operatorsInvolved: Array.from(operatorsSet),
                    underestimatedFields: Array.from(fieldsSet),
                    severityScore: Math.round(severityScore * 100) / 100,
                    contagionIndex: Math.round(contagionIndex * 100) / 100
                });
            }
        }

        // Incorporate compacted base stats into weighted calculations (assume JUNIOR weight 1.0 for compacted ones)
        totalWeightedErrors += (this.compactedUnderestimatedBlastRadiusCount + this.compactedUnderestimatedTelemetryCount) * 1.0;
        totalWeightedPossible += this.compactedResurrectionsCount * 2 * 1.0;

        // Calculate Group Resurrection Bias Score (Weighted)
        let groupResurrectionBiasScore = totalWeightedPossible > 0 ? totalWeightedErrors / totalWeightedPossible : 0.0;

        // Detect Temporal Incident Clustering (errors within 24 hours / 86400000ms of each other)
        let temporalClusteringDetected = false;
        underestimationTimestamps.sort((a, b) => a - b);
        let clusterCount = 0;
        for (let i = 0; i < underestimationTimestamps.length - 1; i++) {
            if (underestimationTimestamps[i + 1] - underestimationTimestamps[i] <= 86400000) {
                temporalClusteringDetected = true;
                clusterCount++;
            }
        }

        if (temporalClusteringDetected) {
            // Clustered incidents amplify the group bias index due to collective panic
            const clusterFactor = Math.min(1.5, 1.0 + (clusterCount * 0.1));
            groupResurrectionBiasScore = groupResurrectionBiasScore * clusterFactor;
        }

        groupResurrectionBiasScore = Math.min(1.0, Math.round(groupResurrectionBiasScore * 100) / 100);

        // Confidence Contagion Factor: lack of review independence
        const confidenceContagionFactor = Math.round(Math.min(1.5, 1.0 + (coSignedUnderestimations * 0.15)) * 100) / 100;

        // Consensus optimism threshold
        const consensusOptimismDetected = groupResurrectionBiasScore > 0.50 && correlatedForecastingFailures.length > 0;

        if (consensusOptimismDetected) {
            warnings.push(`CRITICAL: Group Consensus Optimism Synchronization detected! SRE teams are mutually reinforcing incorrect assumptions and collectively underestimating resurrection impacts.`);
        }
        if (temporalClusteringDetected) {
            warnings.push(`WARNING: Temporal clustering of forecasting failures detected. Multiple underestimations occurred within 24 hours, indicating a panic incident storm.`);
        }

        const groupConsensusBias: GroupConsensusBiasReport = {
            consensusOptimismDetected,
            groupResurrectionBiasScore,
            correlatedForecastingFailures,
            temporalClusteringDetected,
            confidenceContagionFactor
        };

        return {
            totalAudited,
            underestimatedBlastRadiusCount,
            underestimatedTelemetryDeltaCount,
            averagePredictionAccuracy: Math.round(averagePredictionAccuracy * 100) / 100,
            operatorAccuracyScores,
            groupConsensusBias,
            warnings
        };
    }
}

export type StorageConfidenceLevel = 'STRONG_PARITY' | 'ORDERING_AMBIGUITY' | 'PARTIAL_TORN_RISK' | 'FILESYSTEM_CORRUPT';

export interface StorageProvenanceReport {
    confidenceLevel: StorageConfidenceLevel;
    storageTruthConfidence: number; // 0.0 to 1.0 (percentage)
    unverifiableWindowMs: number;
    fsyncBarrierVerified: boolean;
    anomalies: string[];
}

export class StorageConfidenceProvenanceEngine {
    /**
     * Evaluates storage hardware write integrity, checksum mismatches,
     * delayed allocations, and classifies filesystem truth reliability.
     */
    public evaluateStorageProvenance(profile: {
        fsyncBarrierVerified: boolean;
        checksumMatch: boolean;
        writeOrderPreserved: boolean;
        unverifiableDelayMs: number;
        firmwareWarningDetected: boolean;
    }): StorageProvenanceReport {
        let confidenceLevel: StorageConfidenceLevel = 'STRONG_PARITY';
        let storageTruthConfidence = 1.0;
        let unverifiableWindowMs = profile.unverifiableDelayMs;
        const anomalies: string[] = [];

        // 1. Evaluate firmware warnings or severe corruptions
        if (profile.firmwareWarningDetected || !profile.checksumMatch) {
            confidenceLevel = 'FILESYSTEM_CORRUPT';
            storageTruthConfidence = 0.10;
            anomalies.push('Silent SSD firmware block corruption or raw block checksum mismatch detected');
        }

        // 2. Evaluate partial block/torn write risks
        else if (!profile.fsyncBarrierVerified && !profile.writeOrderPreserved) {
            confidenceLevel = 'PARTIAL_TORN_RISK';
            storageTruthConfidence = 0.45;
            anomalies.push('Fsync barriers unconfirmed and hardware write reordering detected (torn-write hazard)');
        }

        // 3. Evaluate ordering ambiguities
        else if (!profile.fsyncBarrierVerified || !profile.writeOrderPreserved) {
            confidenceLevel = 'ORDERING_AMBIGUITY';
            storageTruthConfidence = 0.75;
            anomalies.push('Fsync write barrier was unverified by storage controller driver');
        }

        // 4. Adjust confidence based on unverifiable delays
        if (profile.unverifiableDelayMs > 10000 && confidenceLevel === 'STRONG_PARITY') {
            confidenceLevel = 'ORDERING_AMBIGUITY';
            storageTruthConfidence = 0.85;
            anomalies.push(`Elevated uncommitted filesystem cache delay detected: ${profile.unverifiableDelayMs}ms`);
        }

        return {
            confidenceLevel,
            storageTruthConfidence: Math.round(storageTruthConfidence * 100) / 100,
            unverifiableWindowMs,
            fsyncBarrierVerified: profile.fsyncBarrierVerified,
            anomalies
        };
    }
}

export interface AlertRoutingDecayReport {
  decayIndex: number; // 0 to 100%
  orphanedChannels: string[];
  singlePointsOfFailure: {
    operatorId: string;
    criticalChannels: string[];
  }[];
  isValid: boolean;
}

export interface OnboardingChecklist {
  operatorId: string;
  startDate: string; // ISO String
  attestationDate?: string; // ISO String
  checklistTasks: {
    taskName: string;
    completed: boolean;
  }[];
}

export interface OnboardingEntropyReport {
  averageOnboardingDelayDays: number;
  incompleteTaskRatio: number; // 0 to 1
  onboardingEntropyScore: number; // 0 to 100
  unattestedOperatorCount: number;
  criticalPendingTasks: string[];
}

export interface OperatorInfo {
  operatorId: string;
  communicatesWith: string[]; // List of other operatorIds
  exclusiveSubsystems: string[]; // List of systems/keys only they own
}

export interface TopologyReport {
  tribalKnowledgeIslands: string[];
  isolationIndex: number; // 0 to 100%
  topologyRiskScore: number; // 0 to 100
  isolatedOperators: string[];
}

export class TeamDriftAuditor {
  /**
   * Audits alert routing mapping to ensure all alarms route to active, valid SRE resolvers.
   */
  public auditAlertRoutingDecay(
    routingMap: Map<string, string[]>,
    activeOperators: Set<string>
  ): AlertRoutingDecayReport {
    const orphanedChannels: string[] = [];
    const spofMap = new Map<string, string[]>();

    for (const [channel, operators] of routingMap.entries()) {
      const activeResolvers = operators.filter(op => activeOperators.has(op));

      if (activeResolvers.length === 0) {
        orphanedChannels.push(channel);
      } else if (activeResolvers.length === 1) {
        const spofOp = activeResolvers[0];
        const spofs = spofMap.get(spofOp) ?? [];
        spofs.push(channel);
        spofMap.set(spofOp, spofs);
      }
    }

    const singlePointsOfFailure = Array.from(spofMap.entries()).map(([opId, channels]) => ({
      operatorId: opId,
      criticalChannels: channels
    }));

    const totalChannels = routingMap.size;
    const decayIndex = totalChannels > 0 ? Math.round((orphanedChannels.length / totalChannels) * 100) : 0;
    const isValid = orphanedChannels.length === 0 && singlePointsOfFailure.length === 0;

    return {
      decayIndex,
      orphanedChannels,
      singlePointsOfFailure,
      isValid
    };
  }

  /**
   * Measures completion delay and uncompleted checklists to track onboarding lag and responsibility diffusion.
   */
  public measureOnboardingEntropy(checklists: OnboardingChecklist[]): OnboardingEntropyReport {
    if (checklists.length === 0) {
      return {
        averageOnboardingDelayDays: 0,
        incompleteTaskRatio: 0,
        onboardingEntropyScore: 0,
        unattestedOperatorCount: 0,
        criticalPendingTasks: []
      };
    }

    let totalDelayMs = 0;
    let delayCount = 0;
    let totalTasks = 0;
    let incompleteTasks = 0;
    let unattestedCount = 0;
    const criticalPendingTasks: string[] = [];

    for (const list of checklists) {
      const start = new Date(list.startDate).getTime();

      if (list.attestationDate) {
        const attestation = new Date(list.attestationDate).getTime();
        totalDelayMs += Math.max(0, attestation - start);
        delayCount++;
      } else {
        unattestedCount++;
        // Operator is active but not attested: add current delay
        const currentDelay = Date.now() - start;
        totalDelayMs += Math.max(0, currentDelay);
        delayCount++;
      }

      for (const t of list.checklistTasks) {
        totalTasks++;
        if (!t.completed) {
          incompleteTasks++;
          if (t.taskName.toLowerCase().includes('attestation') || t.taskName.toLowerCase().includes('key')) {
            criticalPendingTasks.push(`${list.operatorId}: ${t.taskName}`);
          }
        }
      }
    }

    const averageOnboardingDelayDays = delayCount > 0 
      ? Math.round((totalDelayMs / (1000 * 60 * 60 * 24)) / delayCount * 10) / 10
      : 0;

    const incompleteTaskRatio = totalTasks > 0 ? incompleteTasks / totalTasks : 0;

    // Onboarding entropy score (0 to 100): combinations of delay and incomplete ratio
    // Assume 30 days is the maximum expected onboarding timeline for baseline scaling
    const delayRatio = Math.min(1.0, averageOnboardingDelayDays / 30);
    const entropyScoreRaw = (delayRatio * 50) + (incompleteTaskRatio * 50);
    const onboardingEntropyScore = Math.round(entropyScoreRaw);

    return {
      averageOnboardingDelayDays,
      incompleteTaskRatio: Math.round(incompleteTaskRatio * 100) / 100,
      onboardingEntropyScore,
      unattestedOperatorCount: unattestedCount,
      criticalPendingTasks
    };
  }

  /**
   * Evaluates team layout topologies to identify isolated operators and tribal knowledge islands.
   */
  public mapTopologyDegradation(operators: OperatorInfo[]): TopologyReport {
    const tribalKnowledgeIslands: string[] = [];
    const isolatedOperators: string[] = [];

    if (operators.length === 0) {
      return {
        tribalKnowledgeIslands,
        isolationIndex: 0,
        topologyRiskScore: 0,
        isolatedOperators
      };
    }

    // Count links and look for exclusive systems
    const subsystemOwners = new Map<string, string[]>();

    for (const op of operators) {
      // Isolated operator: has fewer than 2 consult communication links
      if (op.communicatesWith.length < 2) {
        isolatedOperators.push(op.operatorId);
      }

      for (const sys of op.exclusiveSubsystems) {
        const owners = subsystemOwners.get(sys) ?? [];
        owners.push(op.operatorId);
        subsystemOwners.set(sys, owners);
      }
    }

    // Find tribal knowledge islands (subsystems owned exclusively by exactly 1 operator)
    for (const [sys, owners] of subsystemOwners.entries()) {
      if (owners.length === 1) {
        const soleOwner = owners[0];
        if (!tribalKnowledgeIslands.includes(soleOwner)) {
          tribalKnowledgeIslands.push(soleOwner);
        }
      }
    }

    const isolationIndex = Math.round((isolatedOperators.length / operators.length) * 100);

    // Calculate topology risk score (0 to 100)
    // Risk increases if we have tribal islands or high percentage of isolated operators
    const islandFactor = Math.min(1.0, tribalKnowledgeIslands.length / operators.length);
    const isolationFactor = isolationIndex / 100;
    const topologyRiskScore = Math.round((islandFactor * 60 + isolationFactor * 40) * 100) / 100;

    return {
      tribalKnowledgeIslands,
      isolationIndex,
      topologyRiskScore: Math.round(topologyRiskScore),
      isolatedOperators
    };
  }
}

/**
 * ─── ZTAN Incident Timeline Reconstructor ────────────────────────────────────
 * Generates an auditable chronological trace of system events leading up to a
 * node quarantine lockdown to enable SRE recovery archaeology.
 * ────────────────────────────────────────────────────────────────────────────
 */

export interface IncidentTimelineEvent {
    timestamp: string;
    stage: string;
    description: string;
    status: 'ALERT' | 'INFO' | 'FATAL';
}

export function reconstructIncidentTimeline(errors: string[], generatedAt: Date): IncidentTimelineEvent[] {
    const timeline: IncidentTimelineEvent[] = [];

    // 1. Initial boot log entry
    timeline.push({
        timestamp: new Date(generatedAt.getTime() - 5000).toISOString(),
        stage: 'BOOT_GATE',
        description: 'Initiating ZTAN node boot and startup attestation checks.',
        status: 'INFO'
    });

    // 2. Iterate through validation exceptions
    for (let idx = 0; idx < errors.length; idx++) {
        const err = errors[idx];
        let stage = 'SAFETY_VERIFIER';
        let status: 'ALERT' | 'INFO' | 'FATAL' = 'ALERT';

        if (err.includes('ENV_AUDIT_ERROR') || err.includes('unledgered') || err.includes('shadow')) {
            stage = 'ENV_COMPLIANCE_AUDITOR';
        } else if (err.includes('OPA') || err.includes('policy') || err.includes('rego')) {
            stage = 'OPA_REST_GATE';
        } else if (err.includes('CHECKSUM') || err.includes('integrity') || err.includes('mismatch')) {
            stage = 'STORAGE_MERKLE_CHAIN';
        }

        timeline.push({
            timestamp: new Date(generatedAt.getTime() - 2000 + idx * 500).toISOString(),
            stage,
            description: err,
            status
        });
    }

    // 3. Concluding quarantine lock entry
    timeline.push({
        timestamp: generatedAt.toISOString(),
        stage: 'NODE_QUARANTINE_LOCKED',
        description: 'FATAL: Core runtime invariants failed attestation. Quarantine lockdown activated.',
        status: 'FATAL'
    });

    return timeline;
}

import { PrismaClient } from '@prisma/client';

/**
 * ─── ZTAN Database Outbox & WAL Sequence Exporter ───────────────────────────
 * Dumps and structures recent transaction records from database logs to support
 * chronological parity verifications during failure archaeology.
 * ────────────────────────────────────────────────────────────────────────────
 */

export interface StorageSequenceExport {
    timestamp: string;
    walLogs: any[];
    ledgerBlocks: any[];
}

export async function exportRecentSequences(prisma: PrismaClient, limit = 10): Promise<StorageSequenceExport> {
    try {
        const walLogs = await prisma.ztanWalLog.findMany({
            orderBy: { seq: 'desc' },
            take: limit
        });

        const ledgerBlocks = await prisma.ztanLedgerBlock.findMany({
            orderBy: { id: 'desc' },
            take: limit
        });

        return {
            timestamp: new Date().toISOString(),
            walLogs,
            ledgerBlocks
        };
    } catch (e: any) {
        return {
            timestamp: new Date().toISOString(),
            walLogs: [],
            ledgerBlocks: []
        };
    }
}

/**
 * ZTAN Phase Ω.2 - Cold-Path Exerciser
 * 
 * DESIGN CONSTRAINTS:
 * 1. Passive testing and advisory decay reports only.
 * 2. Never mutates production datasets or upgrades running schemas.
 * 3. Bounded, advisory execution. No autonomous recovery loops.
 */

export interface ColdPathTestVector {
    vectorId: string;
    schemaVersion: string;
    codecId: string;
    rawPayload: string; // Serialised payload representation
    expectedStateHash: string;
}

export interface ColdPathExerciseResult {
    vectorId: string;
    decompressionSuccessful: boolean;
    schemaMigrationSuccessful: boolean;
    hashParityMatched: boolean;
    processingTimeMs: number;
    errorDetails?: string;
}

export interface ColdPathCampaignReport {
    campaignId: string;
    timestamp: number;
    totalVectorsTested: number;
    successfulVectorsCount: number;
    failedVectorsCount: number;
    rotIndicatorScore: number; // 0.0 to 1.0 where 1.0 represents zero detected code rot
    advisoryWarnings: string[];
    vectorDetails: ColdPathExerciseResult[];
}

export class ColdPathExerciser {

    /**
     * Exercises ancient snapshots, old replay formats, and deprecated schema migrations,
     * identifying cold-path compatibility decay before recovery operations demand it.
     */
    public runColdPathCampaign(
        campaignId: string,
        vectors: ColdPathTestVector[]
    ): ColdPathCampaignReport {
        const vectorDetails: ColdPathExerciseResult[] = [];
        const advisoryWarnings: string[] = [];
        let successfulVectorsCount = 0;

        for (const vec of vectors) {
            const start = Date.now();
            let decompressionSuccessful = true;
            let schemaMigrationSuccessful = true;
            let hashParityMatched = true;
            let errorDetails: string | undefined;

            try {
                // 1. Simulate decompression / codec decoding
                if (vec.codecId === 'UNSUPPORTED_ROT') {
                    decompressionSuccessful = false;
                    throw new Error(`Codec compression format '${vec.codecId}' is obsolete or unrecognized.`);
                }

                // 2. Simulate schema compatibility validation & migrations
                const parsedPayload = JSON.parse(vec.rawPayload);
                if (parseFloat(vec.schemaVersion) < 1.0) {
                    // Deprecated schema migration simulation
                    if (parsedPayload.obsoleteField === undefined) {
                        schemaMigrationSuccessful = false;
                        throw new Error(`Schema version '${vec.schemaVersion}' migration failed: missing critical backward compatible parameters.`);
                    }
                }

                // 3. Compute hash parity
                const calculatedHash = this.computeSha256Mock(vec.rawPayload);
                if (calculatedHash !== vec.expectedStateHash) {
                    hashParityMatched = false;
                    throw new Error(`State parity validation failed. Expected: '${vec.expectedStateHash}', Computed: '${calculatedHash}'`);
                }

            } catch (err: any) {
                errorDetails = err.message || String(err);
            }

            const isSuccess = decompressionSuccessful && schemaMigrationSuccessful && hashParityMatched;
            if (isSuccess) {
                successfulVectorsCount++;
            } else {
                advisoryWarnings.push(`Cold path test vector '${vec.vectorId}' (Schema v${vec.schemaVersion}, Codec ${vec.codecId}) failed: ${errorDetails}`);
            }

            vectorDetails.push({
                vectorId: vec.vectorId,
                decompressionSuccessful,
                schemaMigrationSuccessful,
                hashParityMatched,
                processingTimeMs: Date.now() - start,
                errorDetails
            });
        }

        const failedVectorsCount = vectors.length - successfulVectorsCount;
        const rotIndicatorScore = vectors.length > 0
            ? Math.round((successfulVectorsCount / vectors.length) * 100) / 100
            : 1.0;

        if (rotIndicatorScore < 1.0) {
            advisoryWarnings.push(`COLD-PATH ROT WARNING: ${failedVectorsCount} out of ${vectors.length} ancient recovery paths failed verification. Expired codecs or schema migrations detected.`);
        }

        return {
            campaignId,
            timestamp: Date.now(),
            totalVectorsTested: vectors.length,
            successfulVectorsCount,
            failedVectorsCount,
            rotIndicatorScore,
            advisoryWarnings,
            vectorDetails
        };
    }

    private computeSha256Mock(payload: string): string {
        // Deterministic mock hashing for quick test-vector execution
        let hash = 0;
        for (let i = 0; i < payload.length; i++) {
            hash = (hash << 5) - hash + payload.charCodeAt(i);
            hash |= 0;
        }
        return `mock-sha256-${Math.abs(hash)}`;
    }
}

/**
 * ZTAN Phase Ω.4 - Counterfactual Diversity Campaign
 * 
 * DESIGN CONSTRAINTS:
 * 1. Passive modeling of operator hypothesis exploration patterns.
 * 2. Never mutates runtime rules or interrupts operators.
 * 3. Advisory reports only. Zero autonomous recovery loops.
 */

export interface OperatorSessionMetric {
    operatorId: string;
    sessionId: string;
    timestamp: number;
    exploredBranchIds: string[];
    secondsSpentOnAlternativeHypotheses: number;
    totalActiveSeconds: number;
}

export interface HypothesisBranch {
    branchId: string;
    confidence: number;
    isAuthoritativeTimeline: boolean;
}

export interface CounterfactualDiversityReport {
    campaignId: string;
    timestamp: number;
    totalSessionsAudited: number;
    narrativeVarianceScore: number; // 0.0 to 1.0 representing narrative diversity
    cognitiveTunnelingIncidentsCount: number;
    prematureConvergenceRisk: number; // 0.0 to 1.0 overall certainty bias risk
    passed: boolean;
    advisoryWarnings: string[];
}

export class CounterfactualDiversityCampaign {

    /**
     * Calculates the statistical variance in operator narrative exploration.
     * High variance suggests balanced consideration of alternative causal paths.
     */
    public measureNarrativeVariance(sessions: OperatorSessionMetric[]): number {
        if (sessions.length === 0) return 0.0;

        const branchFrequencies = new Map<string, number>();
        let totalExploredCount = 0;

        for (const s of sessions) {
            for (const branch of s.exploredBranchIds) {
                branchFrequencies.set(branch, (branchFrequencies.get(branch) || 0) + 1);
                totalExploredCount++;
            }
        }

        if (totalExploredCount === 0) return 0.0;

        // Compute Shannon entropy over explored branches to represent narrative variance
        let entropy = 0;
        for (const [_, freq] of branchFrequencies.entries()) {
            const p = freq / totalExploredCount;
            entropy -= p * Math.log(p);
        }

        // Normalize index relative to maximum possible entropy log(n)
        const maxEntropy = Math.log(Math.max(2, branchFrequencies.size));
        return Math.round((entropy / maxEntropy) * 100) / 100;
    }

    /**
     * Identifies when an operator has hyper-focused on the primary authoritative timeline,
     * ignoring highly probable competing causal hypothesis branches.
     */
    public detectCognitiveTunneling(
        session: OperatorSessionMetric,
        allBranches: HypothesisBranch[]
    ): { tunnelingDetected: boolean; ignoredRatio: number } {
        // High-confidence alternative branches (confidence > 0.3)
        const highlyProbableAlts = allBranches.filter(b => !b.isAuthoritativeTimeline && b.confidence > 0.3);
        if (highlyProbableAlts.length === 0) {
            return { tunnelingDetected: false, ignoredRatio: 0.0 };
        }

        let exploredAltCount = 0;
        for (const alt of highlyProbableAlts) {
            if (session.exploredBranchIds.includes(alt.branchId)) {
                exploredAltCount++;
            }
        }

        const ignoredRatio = 1.0 - (exploredAltCount / highlyProbableAlts.length);

        // Tunneling is flagged if they ignored more than 80% of highly probable alternative branches
        // AND spent less than 10% of their session time looking at alternative timelines.
        const alternativeTimeRatio = session.totalActiveSeconds > 0
            ? session.secondsSpentOnAlternativeHypotheses / session.totalActiveSeconds
            : 0.0;

        const tunnelingDetected = ignoredRatio > 0.80 && alternativeTimeRatio < 0.10;

        return {
            tunnelingDetected,
            ignoredRatio: Math.round(ignoredRatio * 100) / 100
        };
    }

    /**
     * Runs the Counterfactual Diversity Campaign.
     * Evaluates operator focus and calculates premature convergence risk index.
     */
    public runCounterfactualCampaign(
        campaignId: string,
        sessions: OperatorSessionMetric[],
        branches: HypothesisBranch[]
    ): CounterfactualDiversityReport {
        const advisoryWarnings: string[] = [];
        let cognitiveTunnelingIncidentsCount = 0;

        // 1. Measure overall narrative variance
        const narrativeVarianceScore = this.measureNarrativeVariance(sessions);
        if (narrativeVarianceScore < 0.40) {
            advisoryWarnings.push('LOW NARRATIVE VARIANCE: Operators are considering very few alternative timelines. High risk of systemic tunnel vision.');
        }

        // 2. Audit individual operator sessions for tunneling
        for (const s of sessions) {
            const audit = this.detectCognitiveTunneling(s, branches);
            if (audit.tunnelingDetected) {
                cognitiveTunnelingIncidentsCount++;
                advisoryWarnings.push(`COGNITIVE TUNNELING DETECTED: Operator '${s.operatorId}' spent ${Math.round((s.secondsSpentOnAlternativeHypotheses / s.totalActiveSeconds) * 100)}% time exploring alternatives, ignoring ${Math.round(audit.ignoredRatio * 100)}% of viable hypotheses.`);
            }
        }

        // 3. Compute premature certainty convergence risk index
        let prematureConvergenceRisk = 0.0;
        if (narrativeVarianceScore < 0.50) prematureConvergenceRisk += 0.4;
        if (cognitiveTunnelingIncidentsCount > 0) prematureConvergenceRisk += 0.3;

        // If average session length spends minimal time on counterfactual branches
        let totalAltTime = 0;
        let totalTime = 0;
        sessions.forEach(s => {
            totalAltTime += s.secondsSpentOnAlternativeHypotheses;
            totalTime += s.totalActiveSeconds;
        });
        const avgAltTimeRatio = totalTime > 0 ? totalAltTime / totalTime : 0.0;
        if (avgAltTimeRatio < 0.15) {
            prematureConvergenceRisk += 0.3;
        }

        prematureConvergenceRisk = Math.round(prematureConvergenceRisk * 100) / 100;
        const passed = prematureConvergenceRisk < 0.70;

        if (!passed) {
            advisoryWarnings.push('CRITICAL COGNITIVE COLLAPSE ALERT: Operators display high narrative convergence bias, focusing strictly on confirmation timelines.');
        }

        return {
            campaignId,
            timestamp: Date.now(),
            totalSessionsAudited: sessions.length,
            narrativeVarianceScore,
            cognitiveTunnelingIncidentsCount,
            prematureConvergenceRisk,
            passed,
            advisoryWarnings
        };
    }
}

/**
 * ZTAN Phase Ω.4 - Cross-Witness Divergence Campaign
 * 
 * DESIGN CONSTRAINTS:
 * 1. Passive epistemic discrepancy surfacing across detached witness exports.
 * 2. Never performs distributed consensus or runtime locking.
 * 3. Advisory reports only. Zero autonomous recovery loops.
 */

import crypto from 'crypto';

export interface WitnessExportSummary {
    witnessId: string;
    taskId: string;
    timestamp: number;
    merkleRoot: string;
    sequenceNumber: number;
}

export interface CadenceAnomaly {
    witnessId: string;
    description: string;
    anomalySeverity: 'LOW' | 'MEDIUM' | 'HIGH';
}

export interface DivergenceCampaignReport {
    campaignId: string;
    timestamp: number;
    witnessCount: number;
    totalExportsAudited: number;
    cadenceAnomalies: CadenceAnomaly[];
    divergedTimelinesFound: boolean;
    violations: string[];
    advisoryWarnings: string[];
}

export class CrossWitnessDivergenceCampaign {

    /**
     * Statically inspects witness export logs for suspicious interval silence windows
     * or sudden cadence surges which suggest timeline rewriting or withholding.
     */
    public detectCadenceAnomalies(
        exports: WitnessExportSummary[],
        averageIntervalMs: number = 300000 // 5 minutes standard
    ): CadenceAnomaly[] {
        const anomalies: CadenceAnomaly[] = [];
        if (exports.length < 2) return anomalies;

        // Sort by timestamp
        const sorted = [...exports].sort((a, b) => a.timestamp - b.timestamp);
        const witnessId = sorted[0].witnessId;

        for (let i = 1; i < sorted.length; i++) {
            const diff = sorted[i].timestamp - sorted[i - 1].timestamp;

            // Silence window exceeding 3x the expected average
            if (diff > averageIntervalMs * 3) {
                anomalies.push({
                    witnessId,
                    description: `SUSPICIOUS WITNESS SILENCE: Silence window of ${Math.round(diff / 1000)} seconds detected between sequence ${sorted[i - 1].sequenceNumber} and ${sorted[i].sequenceNumber}.`,
                    anomalySeverity: 'HIGH'
                });
            }

            // Timeline rewrites or sudden bursts (too fast)
            if (diff < averageIntervalMs * 0.05) {
                anomalies.push({
                    witnessId,
                    description: `SUDDEN SEQUENCE BURST: Sequence ${sorted[i].sequenceNumber} exported within ${Math.round(diff / 1000)} seconds. Potential batch timeline manipulation.`,
                    anomalySeverity: 'MEDIUM'
                });
            }
        }

        return anomalies;
    }

    /**
     * Compares Merkle root lineages across two detached witness exports to isolate
     * exactly where history has forked or been selectively omitted by privileged insiders.
     */
    public compareWitnessLineages(
        witnessA: WitnessExportSummary[],
        witnessB: WitnessExportSummary[]
    ): string[] {
        const discrepancies: string[] = [];
        
        // Map sequences to roots
        const mapA = new Map<number, string>();
        witnessA.forEach(x => mapA.set(x.sequenceNumber, x.merkleRoot));

        for (const exp of witnessB) {
            const rootA = mapA.get(exp.sequenceNumber);
            if (rootA && rootA !== exp.merkleRoot) {
                discrepancies.push(`MERKLE LINEAGE FORK: Sequence ${exp.sequenceNumber} has conflicting roots. Witness A: '${rootA}', Witness B: '${exp.merkleRoot}'`);
            }
        }

        return discrepancies;
    }

    /**
     * Runs the Cross-Witness Divergence Campaign.
     * Compares multi-witness exports to surface timeline discrepancies.
     */
    public runDivergenceCampaign(
        campaignId: string,
        witnessData: Record<string, WitnessExportSummary[]>
    ): DivergenceCampaignReport {
        const cadenceAnomalies: CadenceAnomaly[] = [];
        const violations: string[] = [];
        const advisoryWarnings: string[] = [];
        let totalExportsAudited = 0;

        const witnesses = Object.keys(witnessData);
        if (witnesses.length === 0) {
            throw new Error('Divergence campaign requires export summaries from at least one witness.');
        }

        // 1. Audit cadence anomalies per witness
        for (const witnessId of witnesses) {
            const list = witnessData[witnessId];
            totalExportsAudited += list.length;
            const anomalies = this.detectCadenceAnomalies(list);
            cadenceAnomalies.push(...anomalies);
        }

        // 2. Audit inter-witness lineage forks (discrepancy comparison)
        for (let i = 0; i < witnesses.length; i++) {
            const listA = witnessData[witnesses[i]];
            for (let j = i + 1; j < witnesses.length; j++) {
                const listB = witnessData[witnesses[j]];
                const lineageForks = this.compareWitnessLineages(listA, listB);
                
                if (lineageForks.length > 0) {
                    violations.push(...lineageForks);
                }
            }
        }

        // Add warnings for cadence issues
        for (const a of cadenceAnomalies) {
            if (a.anomalySeverity === 'HIGH') {
                advisoryWarnings.push(`Cadence threat detected for ${a.witnessId}: ${a.description}`);
            }
        }

        const divergedTimelinesFound = violations.length > 0;
        if (divergedTimelinesFound) {
            advisoryWarnings.push('CRITICAL DISCREPANCY DETECTED: Chronological lineages have diverged across detached witness nodes. History has been selectively modified or forged by a privileged insider.');
        }

        return {
            campaignId,
            timestamp: Date.now(),
            witnessCount: witnesses.length,
            totalExportsAudited,
            cadenceAnomalies,
            divergedTimelinesFound,
            violations,
            advisoryWarnings
        };
    }
}

