    public clearFault(fault: FaultType): void {
        this.activeFaults.delete(fault);
    }

    /**
     * Checks if a fault is currently active.
     */
    public isFaultActive(fault: FaultType): boolean {
        return this.activeFaults.has(fault);
    }
}

