/**
 * ZTAN Phase Ω.2 - Multi-Operator Divergence Campaign
 * 
 * DESIGN CONSTRAINTS:
 * 1. Passive social/cognitive bias forensics.
 * 2. Never mutates runtime behavior or transitions state.
 * 3. Advisory analysis of timeline selection diversity.
 */

export interface OperatorNarrative {
    operatorId: string;
    timestamp: number;
    selectedEventIds: string[];
    narrativeNotes: string;
}

export interface ConvergencePressureMetric {
    averageJaccardSimilarity: number;
    convergenceThreshold: number;
    isConverged: boolean; // Highly converged suggests cherry-picking / team consensus bias
}

export interface TimelineOmissionReport {
    omittedEventIds: string[];
    omissionRate: number; // omitted/total events
}

export interface NarrativeDivergenceCampaignReport {
    campaignId: string;
    timestamp: number;
    operatorCount: number;
    convergence: ConvergencePressureMetric;
    omissions: TimelineOmissionReport;
    narrativeDiversityIndex: number; // HHI (0.0 to 1.0) where 1.0 represents absolute dominant narrative collapse
    advisoryWarnings: string[];
}

export class MultiOperatorDivergenceCampaign {

    /**
     * Runs the Multi-Operator Divergence Campaign.
     * Evaluates operator narratives against the complete, actual chronological telemetry timeline.
     * Detects alignment bias, omission rates, and narrative convergence pressure.
     */
    public runDivergenceCampaign(
        campaignId: string,
        narratives: OperatorNarrative[],
        completeTimelineEventIds: string[]
    ): NarrativeDivergenceCampaignReport {
        if (narratives.length === 0) {
            throw new Error('Divergence campaign requires at least one operator narrative.');
        }

        const advisoryWarnings: string[] = [];

        // 1. Calculate Jaccard similarity across operator timeline selections (Convergence Pressure)
        const convergence = this.calculateConvergence(narratives);
        if (convergence.isConverged) {
            advisoryWarnings.push('HIGH NARRATIVE CONVERGENCE: Operator timelines are statistically identical. High risk of team consensus bias or dominant-operator cherry-picking.');
        }

        // 2. Calculate Omissions from the definitive timeline
        const omissions = this.calculateOmissions(narratives, completeTimelineEventIds);
        if (omissions.omissionRate > 0.40) {
            advisoryWarnings.push(`HIGH TIMELINE OMISSION: Operators have collectively omitted ${Math.round(omissions.omissionRate * 100)}% of definitive chronological events. Critical forensic evidence may be suppressed.`);
        }

        // 3. Compute Herfindahl-Hirschman Index (HHI) for narrative diversity
        // Identifies if one narrative has collapsed diversity completely (dominated by a single operator)
        const narrativeDiversityIndex = this.calculateNarrativeDiversityIndex(narratives);
        if (narrativeDiversityIndex > 0.80) {
            advisoryWarnings.push('DOMINANT NARRATIVE COLLAPSE: A single operator timeline dominates the collective pool of narratives. Independent verification is highly compromised.');
        }

        return {
            campaignId,
            timestamp: Date.now(),
            operatorCount: narratives.length,
            convergence,
            omissions,
            narrativeDiversityIndex,
            advisoryWarnings
        };
    }

    private calculateConvergence(narratives: OperatorNarrative[]): ConvergencePressureMetric {
        const threshold = 0.85; // Jaccard > 0.85 indicates extreme alignment
        if (narratives.length === 1) {
            return {
                averageJaccardSimilarity: 1.0,
                convergenceThreshold: threshold,
                isConverged: false
            };
        }

        let totalSimilarity = 0;
        let pairsCount = 0;

        for (let i = 0; i < narratives.length; i++) {
            const setA = new Set(narratives[i].selectedEventIds);
            for (let j = i + 1; j < narratives.length; j++) {
                const setB = new Set(narratives[j].selectedEventIds);

                // Jaccard = Intersection / Union
                const intersection = new Set([...setA].filter(x => setB.has(x)));
                const union = new Set([...setA, ...setB]);

                const similarity = union.size > 0 ? intersection.size / union.size : 1.0;
                totalSimilarity += similarity;
                pairsCount++;
            }
        }

        const averageJaccardSimilarity = Math.round((totalSimilarity / pairsCount) * 100) / 100;
        const isConverged = averageJaccardSimilarity >= threshold;

        return {
            averageJaccardSimilarity,
            convergenceThreshold: threshold,
            isConverged
        };
    }

    private calculateOmissions(narratives: OperatorNarrative[], completeTimelineEventIds: string[]): TimelineOmissionReport {
        if (completeTimelineEventIds.length === 0) {
            return { omittedEventIds: [], omissionRate: 0.0 };
        }

        // Collect all event IDs selected by ANY operator
        const selectedByAny = new Set<string>();
        for (const n of narratives) {
            n.selectedEventIds.forEach(id => selectedByAny.add(id));
        }

        // Identify complete timeline events that are completely omitted across all narratives
        const omittedEventIds = completeTimelineEventIds.filter(id => !selectedByAny.has(id));
        const omissionRate = Math.round((omittedEventIds.length / completeTimelineEventIds.length) * 100) / 100;

        return {
            omittedEventIds,
            omissionRate
        };
    }

    private calculateNarrativeDiversityIndex(narratives: OperatorNarrative[]): number {
        // Count frequencies of event occurrences across all operator selections
        const freqMap = new Map<string, number>();
        let totalSelections = 0;

        for (const n of narratives) {
            for (const id of n.selectedEventIds) {
                freqMap.set(id, (freqMap.get(id) || 0) + 1);
                totalSelections++;
            }
        }

        if (totalSelections === 0) return 0.0;

        // Compute HHI = sum of (market shares)^2
        let hhi = 0;
        for (const [_, count] of freqMap.entries()) {
            const share = count / totalSelections;
            hhi += share * share;
        }

        return Math.round(hhi * 100) / 100;
    }
}

import crypto from 'crypto';
import { TelemetryEvent } from './replay-compressor.js';

export interface ChainedTelemetryEvent extends TelemetryEvent {
    previousHash: string;
    hash: string;
}

export interface ProvenanceSignature {
    archiveHash: string;
    signature: string;
    signerId: string;
    timestamp: number;
}

export class EvidenceAuthenticator {
    /**
     * Chains a sequence of telemetry events cryptographically.
     * Each block binds to the previous hash creating a tamper-evident lineage.
     */
    public hashChainTelemetry(events: TelemetryEvent[], genesisHash: string = '0'.repeat(64)): ChainedTelemetryEvent[] {
        const chained: ChainedTelemetryEvent[] = [];
        let prevHash = genesisHash;

        for (const event of events) {
            // Preimage: id || timestamp || type || JSON(payload) || previousHash
            const payloadStr = JSON.stringify(event.payload || {});
            const preimage = `${event.id}${event.timestamp}${event.type}${payloadStr}${prevHash}`;
            
            const hash = crypto.createHash('sha256').update(preimage).digest('hex');

            chained.push({
                ...event,
                previousHash: prevHash,
                hash
            });

            prevHash = hash;
        }

        return chained;
    }

    /**
     * Validates a chained telemetry sequence for historical insertions, modifications, or deletions.
     */
    public validateTelemetryChain(
        chainedEvents: ChainedTelemetryEvent[],
        genesisHash: string = '0'.repeat(64)
    ): { isValid: boolean; brokenIndex: number; errorReason?: string } {
        let expectedPrevHash = genesisHash;

        for (let i = 0; i < chainedEvents.length; i++) {
            const event = chainedEvents[i];

            if (event.previousHash !== expectedPrevHash) {
                return {
                    isValid: false,
                    brokenIndex: i,
                    errorReason: `Hash continuity broken. Expected previousHash: '${expectedPrevHash}', Got: '${event.previousHash}'`
                };
            }

            const payloadStr = JSON.stringify(event.payload || {});
            const preimage = `${event.id}${event.timestamp}${event.type}${payloadStr}${event.previousHash}`;
            const recomputedHash = crypto.createHash('sha256').update(preimage).digest('hex');

            if (event.hash !== recomputedHash) {
                return {
                    isValid: false,
                    brokenIndex: i,
                    errorReason: `Signature hash mismatch. Computed: '${recomputedHash}', Stored: '${event.hash}'`
                };
            }

            expectedPrevHash = event.hash;
        }

        return {
            isValid: true,
            brokenIndex: -1
        };
    }

    /**
     * Signs a telemetry archive/snapshot hash.
     * For high durability without external key setup, we use standard RSA or HMAC signing.
     * Here we utilize ECDSA (secp256k1) or standard RSA signatures, or a secure cryptographic mock for local verification.
     */
    public signArchiveSnapshot(archiveHash: string, privateKeyPem: string): string {
        try {
            const sign = crypto.createSign('SHA256');
            sign.update(archiveHash);
            sign.end();
            return sign.sign(privateKeyPem, 'hex');
        } catch (e) {
            // Fallback to HMAC-SHA256 signature if key formats are not PEM (for drills/tests)
            return crypto.createHmac('sha256', privateKeyPem).update(archiveHash).digest('hex');
        }
    }

    /**
     * Verifies the provenance signature of a telemetry archive/snapshot.
     */
    public verifyArchiveSnapshot(archiveHash: string, signature: string, publicKeyPemOrSecret: string): boolean {
        try {
            const verify = crypto.createVerify('SHA256');
            verify.update(archiveHash);
            verify.end();
            return verify.verify(publicKeyPemOrSecret, signature, 'hex');
        } catch (e) {
            // Fallback to HMAC-SHA256 comparison
            const expectedSig = crypto.createHmac('sha256', publicKeyPemOrSecret).update(archiveHash).digest('hex');
            return expectedSig === signature;
        }
    }
}

import fs from 'fs';
import path from 'path';

/**
 * ─── ZTAN Evidence Compactor & Tiering System ──────────────────────────────────
 * Implements data reduction heuristics for the Evidence Vault, mitigating
 * graph database scalability challenges and disk overhead.
 * ────────────────────────────────────────────────────────────────────────────
 */

export interface CompactorEvent {
  timestampIso: string;
  type: string;
  status: 'NOMINAL' | 'DEGRADED' | 'ANOMALOUS' | 'CRITICAL';
  details?: Record<string, any>;
}

export interface ReplayTrace {
  seqId: number;
  action: string;
  prevStatus: string;
  currentStatus: string;
  diverged: boolean;
  error?: string;
}

export class EvidenceCompactor {
  private vaultDir: string;
  private coldDir: string;

  constructor(workspaceRoot: string) {
    this.vaultDir = path.resolve(workspaceRoot, '.ztan', 'evidence-vault');
    this.coldDir = path.resolve(this.vaultDir, 'cold_archive');
  }

  /**
   * Collapses long linear chains of nominal events into a single summary event.
   */
  public causalityCollapseHeuristics(events: CompactorEvent[]): CompactorEvent[] {
    if (events.length === 0) return [];

    const collapsed: CompactorEvent[] = [];
    let currentNominalChain: CompactorEvent[] = [];

    for (const event of events) {
      if (event.status === 'NOMINAL') {
        currentNominalChain.push(event);
      } else {
        // Flush nominal chain before adding non-nominal event
        if (currentNominalChain.length > 0) {
          collapsed.push(this.collapseChain(currentNominalChain));
          currentNominalChain = [];
        }
        collapsed.push(event);
      }
    }

    if (currentNominalChain.length > 0) {
      collapsed.push(this.collapseChain(currentNominalChain));
    }

    return collapsed;
  }

  /**
   * Filters snapshots to retain boundary states and periodic sparse nominal points.
   */
  public forensicSamplingRules(snapshots: any[], sampleInterval: number = 5): any[] {
    if (snapshots.length <= 2) return [...snapshots];

    const sampled: any[] = [];
    sampled.push(snapshots[0]); // Always keep the initial state

    for (let i = 1; i < snapshots.length - 1; i++) {
      const snap = snapshots[i];
      const isAnomalous = snap.trustStatus !== 'VERIFIED' && snap.trustStatus !== 'NOMINAL';

      // Keep if anomalous or if it hits the sampling interval
      if (isAnomalous || (i % sampleInterval === 0)) {
        sampled.push(snap);
      }
    }

    sampled.push(snapshots[snapshots.length - 1]); // Always keep the final state
    return sampled;
  }

  /**
   * Performs retention tiering by moving old records from hot vault to cold archive.
   */
  public async retentionTiering(maxAgeMs: number = 24 * 60 * 60 * 1000): Promise<{ hotSize: number; coldSize: number; archivedCount: number }> {
    if (!fs.existsSync(this.vaultDir)) {
      return { hotSize: 0, coldSize: 0, archivedCount: 0 };
    }
    if (!fs.existsSync(this.coldDir)) {
      fs.mkdirSync(this.coldDir, { recursive: true });
    }

    const now = Date.now();
    const files = fs.readdirSync(this.vaultDir);
    let archivedCount = 0;
    const coldBundleData: Record<string, string> = {};

    for (const file of files) {
      const filePath = path.join(this.vaultDir, file);
      const stat = fs.statSync(filePath);

      if (stat.isDirectory()) continue;

      const isProtected = file.startsWith('incident-') || file.includes('protected');
      const age = now - stat.mtimeMs;

      if (!isProtected && age > maxAgeMs) {
        try {
          const content = fs.readFileSync(filePath, 'utf8');
          coldBundleData[file] = content;

          // Delete from hot vault
          fs.unlinkSync(filePath);
          archivedCount++;
        } catch (err) {
          console.error(`[EvidenceCompactor] Failed to archive ${file}:`, err);
        }
      }
    }

    let coldSize = 0;
    if (archivedCount > 0) {
      // Write to cold directory in a unified compact archive
      const archiveName = `archive-${now}.json`;
      const coldFilePath = path.join(this.coldDir, archiveName);
      fs.writeFileSync(coldFilePath, JSON.stringify(coldBundleData), 'utf8');
      coldSize = fs.statSync(coldFilePath).size;
    }

    // Calculate current hot size
    let hotSize = 0;
    const remainingFiles = fs.readdirSync(this.vaultDir);
    for (const file of remainingFiles) {
      const filePath = path.join(this.vaultDir, file);
      const stat = fs.statSync(filePath);
      if (!stat.isDirectory()) {
        hotSize += stat.size;
      }
    }

    return {
      hotSize,
      coldSize,
      archivedCount
    };
  }

  /**
   * Filters replay traces to keep only divergence boundaries, state transitions, and faults.
   */
  public replaySummarization(replayHistory: ReplayTrace[]): ReplayTrace[] {
    return replayHistory.filter(trace => {
      const isTransition = trace.prevStatus !== trace.currentStatus;
      return isTransition || trace.diverged || !!trace.error;
    });
  }

  // --- PRIVATE UTILITIES ---

  private collapseChain(chain: CompactorEvent[]): CompactorEvent {
    if (chain.length === 1) return chain[0];

    return {
      timestampIso: chain[0].timestampIso,
      type: 'CAUSAL_COLLAPSE_SUMMARY',
      status: 'NOMINAL',
      details: {
        collapsedCount: chain.length,
        endTimeIso: chain[chain.length - 1].timestampIso,
        eventTypes: Array.from(new Set(chain.map(e => e.type)))
      }
    };
  }
}

import fs from 'fs';
import path from 'path';

/**
 * ─── ZTAN Evidence Retention Enforcer ────────────────────────────────────────
 * Mechanically manages the storage overhead of the Evidence Vault. Expired
 * telemetry is pruned based on TTL limits, and storage pressure thresholds
 * trigger deletion of oldest files first, keeping incident snapshots protected.
 * ────────────────────────────────────────────────────────────────────────────
 */

export interface PruneStats {
    scannedCount: number;
    deletedCount: number;
    reclaimedBytes: number;
    errors: string[];
}

export class EvidenceRetentionEnforcer {
    private vaultDir: string;
    private maxSizeBytes: number;
    private fileTtlMs: number;

    constructor(workspaceRoot: string, maxSizeBytes: number = 50 * 1024 * 1024, fileTtlMs: number = 7 * 24 * 60 * 60 * 1000) {
        this.vaultDir = path.resolve(workspaceRoot, '.ztan', 'evidence-vault');
        this.maxSizeBytes = maxSizeBytes;
        this.fileTtlMs = fileTtlMs;
    }

    private getAllFiles(dir: string): string[] {
        let files: string[] = [];
        if (!fs.existsSync(dir)) return files;
        const list = fs.readdirSync(dir);
        for (const item of list) {
            const fullPath = path.join(dir, item);
            const stat = fs.statSync(fullPath);
            if (stat.isDirectory()) {
                files = files.concat(this.getAllFiles(fullPath));
            } else {
                files.push(fullPath);
            }
        }
        return files;
    }

    /**
     * Scans and cleans up files violating TTL and storage space budgets.
     */
    enforce(): PruneStats {
        const stats: PruneStats = {
            scannedCount: 0,
            deletedCount: 0,
            reclaimedBytes: 0,
            errors: []
        };

        try {
            const files = this.getAllFiles(this.vaultDir);
            stats.scannedCount = files.length;

            const now = Date.now();
            const eligibleFiles: Array<{ filePath: string; mtimeMs: number; sizeBytes: number; isProtected: boolean }> = [];
            let totalVaultSize = 0;

            for (const file of files) {
                const stat = fs.statSync(file);
                totalVaultSize += stat.size;

                // Protect raw incidents or explicit protected tags from general cleanup
                const basename = path.basename(file);
                const isProtected = basename.startsWith('incident-') || basename.includes('protected');

                eligibleFiles.push({
                    filePath: file,
                    mtimeMs: stat.mtimeMs,
                    sizeBytes: stat.size,
                    isProtected
                });
            }

            // 1. Pass 1: Prune expired records (older than TTL)
            for (const file of eligibleFiles) {
                if (!file.isProtected && (now - file.mtimeMs) > this.fileTtlMs) {
                    try {
                        fs.unlinkSync(file.filePath);
                        stats.deletedCount++;
                        stats.reclaimedBytes += file.sizeBytes;
                        totalVaultSize -= file.sizeBytes;
                    } catch (err: any) {
                        stats.errors.push(`Failed to delete expired file ${file.filePath}: ${err.message}`);
                    }
                }
            }

            // 2. Pass 2: Clean up oldest non-protected files under storage pressure
            if (totalVaultSize > this.maxSizeBytes) {
                const sortedUnprotected = eligibleFiles
                    .filter(f => !f.isProtected && fs.existsSync(f.filePath))
                    .sort((a, b) => a.mtimeMs - b.mtimeMs);

                for (const file of sortedUnprotected) {
                    if (totalVaultSize <= this.maxSizeBytes) {
                        break;
                    }
                    try {
                        fs.unlinkSync(file.filePath);
                        stats.deletedCount++;
                        stats.reclaimedBytes += file.sizeBytes;
                        totalVaultSize -= file.sizeBytes;
                    } catch (err: any) {
                        stats.errors.push(`Failed to delete storage-pressure file ${file.filePath}: ${err.message}`);
                    }
                }
            }
        } catch (err: any) {
            stats.errors.push(`Scan execution error: ${err.message}`);
        }

        return stats;
    }
}

import { TelemetryEvent } from './replay-compressor.js';

export interface SchemaMigration {
    sourceVersion: string;
    targetVersion: string;
    transform: (event: any) => any;
}

export interface ArchivedValidator {
    ruleName: string;
    version: string;
    validate: (inputs: Record<string, any>) => boolean;
}

export class HistoricalReplayCompatibility {
    private migrations = new Map<string, SchemaMigration[]>();
    private validators = new Map<string, ArchivedValidator>();

    /**
     * Registers a schema migration pathway
     */
    public registerMigration(migration: SchemaMigration): void {
        const key = `${migration.sourceVersion}->${migration.targetVersion}`;
        const existing = this.migrations.get(key) || [];
        existing.push(migration);
        this.migrations.set(key, existing);
    }

    /**
     * Registers an archived validator
     */
    public registerArchivedValidator(validator: ArchivedValidator): void {
        const key = `${validator.ruleName}@${validator.version}`;
        this.validators.set(key, validator);
    }

    /**
     * Up-casts deprecated telemetry events to match the latest schema structures.
     */
    public reconstructLegacyEvent(legacyEvent: any, sourceVersion: string, targetVersion: string): TelemetryEvent {
        let currentEvent = { ...legacyEvent };
        
        const key = `${sourceVersion}->${targetVersion}`;
        const migrationsToApply = this.migrations.get(key);
        if (migrationsToApply) {
            for (const migration of migrationsToApply) {
                currentEvent = migration.transform(currentEvent);
            }
        } else {
            // Apply fallback default upgrades if no migration registered
            if (currentEvent.id === undefined) currentEvent.id = `legacy-${Math.random().toString(36).substring(2, 11)}`;
            if (currentEvent.type === undefined) currentEvent.type = 'LEGACY_EVENT';
            if (currentEvent.timestamp === undefined) currentEvent.timestamp = Date.now();
            if (currentEvent.entropyScore === undefined) currentEvent.entropyScore = 0.0;
            
            const payload: Record<string, any> = currentEvent.payload ? { ...currentEvent.payload } : {};
            for (const k of Object.keys(currentEvent)) {
                if (!['id', 'type', 'timestamp', 'entropyScore', 'payload'].includes(k)) {
                    payload[k] = currentEvent[k];
                }
            }
            currentEvent.payload = payload;
        }

        // Add compatibility metadata layer
        currentEvent.payload = {
            ...currentEvent.payload,
            _compatibility: {
                upcasted: true,
                originalVersion: sourceVersion,
                targetVersion: targetVersion,
                upcastedAt: Date.now()
            }
        };

        return currentEvent as TelemetryEvent;
    }

    /**
     * Evaluates legacy validation assertions for retired rules when replaying historical traces.
     */
    public emulateArchivedValidator(ruleName: string, version: string, inputs: Record<string, any>): boolean {
        const key = `${ruleName}@${version}`;
        const validator = this.validators.get(key);
        if (!validator) {
            // Fallback default emulation: if no validator, check if inputs has any keys
            return Object.keys(inputs).length > 0;
        }
        try {
            return validator.validate(inputs);
        } catch (err) {
            return false;
        }
    }
}

export interface TelemetryEvent {
    id: string;
    type: string;
    timestamp: number;
    entropyScore: number; // 0.0 to 1.0 (anomalous scale)
    payload: Record<string, any>;
}

export interface CausalGraph {
    nodes: Array<{ id: string; type: string; importance: number }>;
    edges: Array<{ from: string; to: string; relationship: string }>;
}

export interface CompressedGraph {
    nodes: Array<{ id: string; type: string; importance: number }>;
    edges: Array<{ from: string; to: string; relationship: string }>;
    prunedNodeCount: number;
}

export interface ReplayTrace {
    traceId: string;
    steps: Array<{ index: number; action: string; stateHash: string; timestamp: number }>;
}

export interface DeltaEncodedTrace {
    traceId: string;
    baseTraceId: string | null;
    addedSteps: Array<{ index: number; action: string; stateHash: string; timestamp: number }>;
    removedStepIndices: number[];
}

export interface Timeline {
    events: TelemetryEvent[];
}

export interface CondensedTimeline {
    segments: Array<{
        startTime: number;
        endTime: number;
        eventType: string;
        eventCount: number;
        dominantEntropyScore: number;
    }>;
}

export class ReplayCompressor {
    /**
     * Prunes causality graph nodes whose importance score falls below a threshold (default 0.30).
     * Connective integrity is maintained by filtering edges.
     */
    public compressCausalityGraph(graph: CausalGraph, minImportance: number = 0.3): CompressedGraph {
        const keptNodes = graph.nodes.filter(node => node.importance >= minImportance);
        const keptNodeIds = new Set(keptNodes.map(n => n.id));

        const keptEdges = graph.edges.filter(edge => 
            keptNodeIds.has(edge.from) && keptNodeIds.has(edge.to)
        );

        return {
            nodes: keptNodes,
            edges: keptEdges,
            prunedNodeCount: graph.nodes.length - keptNodes.length
        };
    }

    /**
     * Deduplicates consecutive redundant events (e.g. heartbeat loops)
     * while preserving first, last, and high-entropy spikes in the sequence.
     */
    public semanticDeduplication(events: TelemetryEvent[]): TelemetryEvent[] {
        if (events.length <= 2) return [...events];

        const result: TelemetryEvent[] = [];
        let runType = events[0].type;
        let runStartIdx = 0;

        const flushRun = (endIdx: number) => {
            result.push(events[runStartIdx]); // Keep first

            // Look for any high-entropy anomaly spikes within the run
            for (let i = runStartIdx + 1; i < endIdx; i++) {
                if (events[i].entropyScore >= 0.7) {
                    result.push(events[i]);
                }
            }

            if (endIdx > runStartIdx) {
                result.push(events[endIdx]); // Keep last
            }
        };

        for (let i = 1; i < events.length; i++) {
            if (events[i].type !== runType) {
                flushRun(i - 1);
                runType = events[i].type;
                runStartIdx = i;
            }
        }
        flushRun(events.length - 1);

        return result;
    }

    /**
     * Enforces anomaly-first storage by discarding regular metrics (low entropy) and retaining anomaly spikes.
     */
    public anomalyFirstRetention(events: TelemetryEvent[], scoreThreshold: number = 0.3): TelemetryEvent[] {
        return events.filter(event => event.entropyScore >= scoreThreshold);
    }

    /**
     * Encodes subsequent execution traces as diffs/deltas relative to a base trace.
     */
    public replayDeltaEncoding(traces: ReplayTrace[]): DeltaEncodedTrace[] {
        if (traces.length === 0) return [];

        const encoded: DeltaEncodedTrace[] = [];
        const base = traces[0];

        // First trace acts as full baseline
        encoded.push({
            traceId: base.traceId,
            baseTraceId: null,
            addedSteps: base.steps,
            removedStepIndices: []
        });

        for (let i = 1; i < traces.length; i++) {
            const current = traces[i];
            const addedSteps: DeltaEncodedTrace['addedSteps'] = [];
            const removedStepIndices: number[] = [];

            // Simple diff: match step index actions and hashes
            const maxLen = Math.max(base.steps.length, current.steps.length);
            for (let j = 0; j < maxLen; j++) {
                const baseStep = base.steps[j];
                const curStep = current.steps[j];

                if (baseStep && curStep) {
                    if (baseStep.action !== curStep.action || baseStep.stateHash !== curStep.stateHash) {
                        // Conflict/Difference: treat as added replacement
                        addedSteps.push(curStep);
                    }
                } else if (curStep) {
                    // Added step
                    addedSteps.push(curStep);
                } else if (baseStep) {
                    // Removed step
                    removedStepIndices.push(baseStep.index);
                }
            }

            encoded.push({
                traceId: current.traceId,
                baseTraceId: base.traceId,
                addedSteps,
                removedStepIndices
            });
        }

        return encoded;
    }

    /**
     * Condenses timeline intervals (e.g. 5-minute segments) to prevent SRE cognitive fatigue.
     */
    public timelineCondensation(timeline: Timeline, intervalMs: number = 300000): CondensedTimeline {
        if (timeline.events.length === 0) return { segments: [] };

        const sorted = [...timeline.events].sort((a, b) => a.timestamp - b.timestamp);
        const segments: CondensedTimeline['segments'] = [];

        let currentSegment: {
            startTime: number;
            endTime: number;
            eventType: string;
            eventCount: number;
            maxEntropy: number;
        } | null = null;

        for (const event of sorted) {
            const bucketStart = Math.floor(event.timestamp / intervalMs) * intervalMs;

            if (currentSegment && currentSegment.startTime === bucketStart && currentSegment.eventType === event.type) {
                currentSegment.eventCount++;
                currentSegment.endTime = event.timestamp;
                if (event.entropyScore > currentSegment.maxEntropy) {
                    currentSegment.maxEntropy = event.entropyScore;
                }
            } else {
                if (currentSegment) {
                    segments.push({
                        startTime: currentSegment.startTime,
                        endTime: currentSegment.endTime,
                        eventType: currentSegment.eventType,
                        eventCount: currentSegment.eventCount,
                        dominantEntropyScore: currentSegment.maxEntropy
                    });
                }
                currentSegment = {
                    startTime: bucketStart,
                    endTime: event.timestamp,
                    eventType: event.type,
                    eventCount: 1,
                    maxEntropy: event.entropyScore
                };
            }
        }

        if (currentSegment) {
            segments.push({
                startTime: currentSegment.startTime,
                endTime: currentSegment.endTime,
                eventType: currentSegment.eventType,
                eventCount: currentSegment.eventCount,
                dominantEntropyScore: currentSegment.maxEntropy
            });
        }

        return { segments };
    }
}

import fs from 'fs';

/**
 * ─── ZTAN Schema Compatibility Validator ─────────────────────────────────────
 * Asserts contract schemas on historical JSON evidence and logs. Allows
 * backward-compatibility validation and provides hooks to apply migration transforms.
 * ────────────────────────────────────────────────────────────────────────────
 */

export interface SchemaValidationResult {
    isValid: boolean;
    missingFields: string[];
    migrationApplied: boolean;
    errors: string[];
}

export class SchemaCompatibilityValidator {
    /**
     * Validates that a file's JSON payload conforms to required field properties.
     */
    validateFile(filePath: string, requiredFields: string[]): SchemaValidationResult {
        const result: SchemaValidationResult = {
            isValid: true,
            missingFields: [],
            migrationApplied: false,
            errors: []
        };

        try {
            if (!fs.existsSync(filePath)) {
                result.isValid = false;
                result.errors.push(`File not found: ${filePath}`);
                return result;
            }

            const raw = fs.readFileSync(filePath, 'utf8');
            let data: any;
            try {
                data = JSON.parse(raw);
            } catch (err: any) {
                result.isValid = false;
                result.errors.push(`Invalid JSON syntax in file: ${err.message}`);
                return result;
            }

            for (const field of requiredFields) {
                if (data[field] === undefined) {
                    result.isValid = false;
                    result.missingFields.push(field);
                }
            }
        } catch (err: any) {
            result.isValid = false;
            result.errors.push(`System validation error: ${err.message}`);
        }

        return result;
    }

    /**
     * Applies a migration transform to map older schema records to current formats.
     */
    migrate(filePath: string, migrationFn: (oldData: any) => any): SchemaValidationResult {
        const result: SchemaValidationResult = {
            isValid: true,
            missingFields: [],
            migrationApplied: false,
            errors: []
        };

        try {
            if (!fs.existsSync(filePath)) {
                result.isValid = false;
                result.errors.push(`File not found: ${filePath}`);
                return result;
            }

            const raw = fs.readFileSync(filePath, 'utf8');
            let data: any;
            try {
                data = JSON.parse(raw);
            } catch (err: any) {
                result.isValid = false;
                result.errors.push(`Invalid JSON syntax in file: ${err.message}`);
                return result;
            }

            const migrated = migrationFn(data);
            fs.writeFileSync(filePath, JSON.stringify(migrated, null, 2), 'utf8');
            result.migrationApplied = true;
        } catch (err: any) {
            result.isValid = false;
            result.errors.push(`Migration execution error: ${err.message}`);
        }

        return result;
    }
}

export interface WorkflowNode {
    id: string;
    actionType: string;
    payload: any;
}

export interface WorkflowEdge {
    from: string;
    to: string;
}

export interface WorkflowGraph {
    nodes: WorkflowNode[];
    edges: WorkflowEdge[];
}

export class BoundedWorkflowEngine {
    /**
     * Validates whether a workflow graph is a valid Directed Acyclic Graph (DAG).
     * Rejects graphs containing self-references or recursive cycles.
     */
    public validateWorkflowDAG(graph: WorkflowGraph): { isDag: boolean; error?: string } {
        const adjList = new Map<string, string[]>();
        const inDegree = new Map<string, number>();

        // Initialize nodes
        for (const node of graph.nodes) {
            adjList.set(node.id, []);
            inDegree.set(node.id, 0);
        }

        // Build adjacency list and calculate in-degrees
        for (const edge of graph.edges) {
            // Check self-reference
            if (edge.from === edge.to) {
                return { isDag: false, error: `Self-reference detected on node: "${edge.from}"` };
            }
            if (!adjList.has(edge.from) || !adjList.has(edge.to)) {
                return { isDag: false, error: `Edge referencing non-existent nodes: "${edge.from} -> ${edge.to}"` };
            }
            adjList.get(edge.from)!.push(edge.to);
            inDegree.set(edge.to, (inDegree.get(edge.to) || 0) + 1);
        }

        // Kahn's algorithm for topological sorting / cycle detection
        const queue: string[] = [];
        for (const [nodeId, deg] of inDegree.entries()) {
            if (deg === 0) {
                queue.push(nodeId);
            }
        }

        let visitedCount = 0;
        while (queue.length > 0) {
            const current = queue.shift()!;
            visitedCount++;

            const neighbors = adjList.get(current) || [];
            for (const neighbor of neighbors) {
                inDegree.set(neighbor, inDegree.get(neighbor)! - 1);
                if (inDegree.get(neighbor) === 0) {
                    queue.push(neighbor);
                }
            }
        }

        const isDag = visitedCount === graph.nodes.length;
        return {
            isDag,
            error: isDag ? undefined : 'Recursive loop or cycle detected in workflow graph topology'
        };
    }
}

import { ExecutionJournal, JournalEntry } from './execution-journal.js';
import { TaskState } from './task-lifecycle-engine.js';

export interface CheckpointEntry {
    taskId: string;
    stepIndex: number;
    state: TaskState;
    consolidatedStatePayload: any;
    timestamp: number;
}

export class CompactedExecutionJournal extends ExecutionJournal {
    private checkpoints = new Map<string, CheckpointEntry>();

    /**
     * Captures a consolidated state checkpoint snapshot for a specific task.
     */
    public checkpointSnapshot(
        taskId: string,
        stepIndex: number,
        state: TaskState,
        consolidatedStatePayload: any
    ): CheckpointEntry {
        const checkpoint: CheckpointEntry = {
            taskId,
            stepIndex,
            state,
            consolidatedStatePayload: JSON.parse(JSON.stringify(consolidatedStatePayload)), // Deep copy
            timestamp: Date.now()
        };

        this.checkpoints.set(taskId, checkpoint);

        // Also append a checkpoint marker entry to the standard WAL journal
        this.appendEntry(taskId, stepIndex, state, {
            isCheckpoint: true,
            checkpointStepIndex: stepIndex
        });

        return checkpoint;
    }

    /**
     * Gets the latest active checkpoint for a task.
     */
    public getCheckpoint(taskId: string): CheckpointEntry | undefined {
        return this.checkpoints.get(taskId);
    }

    /**
     * Prunes detailed historical intermediate journal entries older than the latest checkpoint
     * to mitigate WAL storage space amplification.
     */
    public compactJournal(taskId: string): { prunedCount: number } {
        const checkpoint = this.checkpoints.get(taskId);
        if (!checkpoint) {
            return { prunedCount: 0 };
        }

        const checkpointStepIndex = checkpoint.stepIndex;
        const initialCount = this.journal.length;

        // Keep all entries that do not belong to the target task,
        // or target task entries that are at or after the checkpoint step index.
        this.journal = this.journal.filter(entry => {
            if (entry.taskId !== taskId) {
                return true;
            }
            return entry.stepIndex >= checkpointStepIndex;
        });

        const finalCount = this.journal.length;
        return { prunedCount: initialCount - finalCount };
    }

    /**
     * Reconstructs the task state and baseline payload, taking active checkpoints into account.
     */
    public reconstructTaskStateWithCompaction(taskId: string): {
        lastStepIndex: number;
        lastState: TaskState | null;
        baselineState: any;
    } {
        const checkpoint = this.checkpoints.get(taskId);
        
        if (!checkpoint) {
            // No checkpoint exists: fallback to standard journal reconstruction
            const standardReconstruction = this.reconstructTaskState(taskId);
            return {
                lastStepIndex: standardReconstruction.lastStepIndex,
                lastState: standardReconstruction.lastState,
                baselineState: null
            };
        }

        // Get post-checkpoint journal entries
        const postCheckpointEntries = this.journal
            .filter(entry => entry.taskId === taskId && entry.stepIndex > checkpoint.stepIndex)
            .sort((a, b) => a.stepIndex - b.stepIndex);

        if (postCheckpointEntries.length === 0) {
            return {
                lastStepIndex: checkpoint.stepIndex,
                lastState: checkpoint.state,
                baselineState: checkpoint.consolidatedStatePayload
            };
        }

        const lastEntry = postCheckpointEntries[postCheckpointEntries.length - 1];
        return {
            lastStepIndex: lastEntry.stepIndex,
            lastState: lastEntry.state,
            baselineState: checkpoint.consolidatedStatePayload
        };
    }
}

export interface ExecutionContract {
    expectedInputs: string[];
    expectedOutputs: string[];
    allowOptional: boolean;
}

export interface ContractValidationReport {
    isValid: boolean;
    missingInputs: string[];
    missingOutputs: string[];
    unexpectedKeys: string[];
    error?: string;
}

export class ExecutionContractValidator {
    /**
     * Validates input/output contracts.
     */
    public validateContract(
        contract: ExecutionContract,
        inputs: Record<string, any>,
        outputs: Record<string, any>
    ): ContractValidationReport {
        const missingInputs: string[] = [];
        const missingOutputs: string[] = [];
        const unexpectedKeys: string[] = [];

        // 1. Verify mandatory input keys are present
        for (const inputKey of contract.expectedInputs) {
            if (!(inputKey in inputs)) {
                missingInputs.push(inputKey);
            }
        }

        // 2. Verify mandatory output keys are present
        for (const outputKey of contract.expectedOutputs) {
            if (!(outputKey in outputs)) {
                missingOutputs.push(outputKey);
            }
        }

        // 3. Verify no unexpected keys exist if allowOptional is false
        if (!contract.allowOptional) {
            const contractInputSet = new Set(contract.expectedInputs);
            for (const key of Object.keys(inputs)) {
                if (!contractInputSet.has(key)) {
                    unexpectedKeys.push(key);
                }
            }
        }

        const isValid = missingInputs.length === 0 && missingOutputs.length === 0 && unexpectedKeys.length === 0;
        let error: string | undefined;

        if (!isValid) {
            error = `Contract validation failed: missingInputs=[${missingInputs.join(', ')}], missingOutputs=[${missingOutputs.join(', ')}], unexpectedKeys=[${unexpectedKeys.join(', ')}]`;
        }

        return {
            isValid,
            missingInputs,
            missingOutputs,
            unexpectedKeys,
            error
        };
    }
}

import { TaskState, TaskLifecycleEngine } from './task-lifecycle-engine.js';
import { ExecutionJournal } from './execution-journal.js';
import { SandboxSupervisor, SandboxResourceUsage } from './sandbox-supervisor.js';
import { ExecutionContractValidator, ExecutionContract } from './execution-contract-validator.js';
import { ExecutionCapabilityRegistry, ExecutionCapability } from './execution-capability-registry.js';
import { RollbackCoordinator, ExecutionStep, RollbackAction } from './rollback-coordinator.js';
import { BoundedWorkflowEngine, WorkflowGraph } from './bounded-workflow-engine.js';

export interface ExecutionOrchestratorConfig {
    maxMemoryMb?: number;
    initialCapabilities?: ExecutionCapability[];
}

export interface ExecutionTaskResult {
    taskId: string;
    finalState: TaskState;
    completedStepsCount: number;
    sandboxViolationDetected: boolean;
    contractValid: boolean;
    rollbackExecuted: boolean;
    rollbackSuccess?: boolean;
    error?: string;
}

export class ExecutionCoordinator {
    private lifecycleEngine = new TaskLifecycleEngine();
    private journal = new ExecutionJournal();
    private sandboxSupervisor: SandboxSupervisor;
    private contractValidator = new ExecutionContractValidator();
    private capabilityRegistry: ExecutionCapabilityRegistry;
    private rollbackCoordinator = new RollbackCoordinator();
    private workflowEngine = new BoundedWorkflowEngine();

    private activeTaskStates = new Map<string, TaskState>();
    private completedSteps = new Map<string, ExecutionStep[]>();
    private idempotencyKeys = new Set<string>();

    constructor(config: ExecutionOrchestratorConfig = {}) {
        this.sandboxSupervisor = new SandboxSupervisor(config.maxMemoryMb || 512);
        this.capabilityRegistry = new ExecutionCapabilityRegistry(config.initialCapabilities || []);
    }

    /**
     * Executes a single task step safely, running it through the complete set of sandbox, capabilities,
     * journaling, and contract gates.
     */
    public async executeTaskStep(params: {
        taskId: string;
        stepIndex: number;
        actionType: string;
        payload: any;
        requiredCapabilities: ExecutionCapability[];
        contract: ExecutionContract;
        sandboxResources: SandboxResourceUsage;
        executedSyscalls: string[];
        idempotencyKey?: string;
        stepExecutor: (step: ExecutionStep) => Promise<Record<string, any>>;
        rollbackExecutor: (action: RollbackAction) => Promise<void>;
    }): Promise<ExecutionTaskResult> {
        const { taskId, stepIndex, actionType, payload, requiredCapabilities, contract, sandboxResources, executedSyscalls, idempotencyKey } = params;

        // 1. Enforce idempotency key check
        if (idempotencyKey) {
            if (this.idempotencyKeys.has(idempotencyKey)) {
                return {
                    taskId,
                    finalState: this.activeTaskStates.get(taskId) || 'SUCCESS',
                    completedStepsCount: this.completedSteps.get(taskId)?.length || 0,
                    sandboxViolationDetected: false,
                    contractValid: true,
                    rollbackExecuted: false,
                    error: `Idempotency violation: step already executed for key "${idempotencyKey}"`
                };
            }
            this.idempotencyKeys.add(idempotencyKey);
        }

        // 2. Initialize task state
        let currentState = this.activeTaskStates.get(taskId) || 'INIT';
        if (currentState === 'INIT') {
            const trans = this.lifecycleEngine.transitionState(taskId, 'INIT', 'RUNNING');
            if (!trans.success) {
                return { taskId, finalState: 'INIT', completedStepsCount: 0, sandboxViolationDetected: false, contractValid: false, rollbackExecuted: false, error: trans.error };
            }
            currentState = 'RUNNING';
            this.activeTaskStates.set(taskId, currentState);
            this.journal.appendEntry(taskId, stepIndex, currentState, { taskStart: true });
        }

        if (currentState !== 'RUNNING') {
            return {
                taskId,
                finalState: currentState,
                completedStepsCount: this.completedSteps.get(taskId)?.length || 0,
                sandboxViolationDetected: false,
                contractValid: false,
                rollbackExecuted: false,
                error: `Cannot execute step on task in state ${currentState}`
            };
        }

        // 3. Enforce capability registry checks
        const capAudit = this.capabilityRegistry.auditRequestedCapabilities(requiredCapabilities);
        if (!capAudit.authorized) {
            const err = `Execution capability registry violation: task requested unauthorized permissions [${capAudit.unauthorizedCapabilities.join(', ')}]`;
            return await this.handleTaskFailure(taskId, stepIndex, err, params.rollbackExecutor);
        }

        // 4. Enforce sandbox supervisor limits
        const sandboxReport = this.sandboxSupervisor.superviseSandbox(sandboxResources, executedSyscalls);
        if (sandboxReport.quarantineTriggered || !sandboxReport.resourceCompliant) {
            const err = `Sandbox supervisor violation: ${sandboxReport.violations.join('; ')}`;
            return await this.handleTaskFailure(taskId, stepIndex, err, params.rollbackExecutor, true);
        }

        // 5. Execute action step
        const currentStep: ExecutionStep = { actionType, payload };
        let output: Record<string, any>;
        try {
            output = await params.stepExecutor(currentStep);

            // Record completed step
            const steps = this.completedSteps.get(taskId) || [];
            steps.push(currentStep);
            this.completedSteps.set(taskId, steps);
        } catch (execErr: any) {
            const err = `Task execution action failed: ${execErr.message || execErr}`;
            return await this.handleTaskFailure(taskId, stepIndex, err, params.rollbackExecutor);
        }

        // 6. Enforce execution output contract verification
        const contractReport = this.contractValidator.validateContract(contract, payload, output);
        if (!contractReport.isValid) {
            const err = `Execution contract validation failure: ${contractReport.error}`;
            return await this.handleTaskFailure(taskId, stepIndex, err, params.rollbackExecutor);
        }

        // 7. Append state entry successfully to the WAL journal
        this.journal.appendEntry(taskId, stepIndex, 'RUNNING', { completedStep: actionType });

        return {
            taskId,
            finalState: 'RUNNING',
            completedStepsCount: this.completedSteps.get(taskId)?.length || 0,
            sandboxViolationDetected: false,
            contractValid: true,
            rollbackExecuted: false
        };
    }

    /**
     * Finalizes task execution state to success.
     */
    public finalizeTaskSuccess(taskId: string): ExecutionTaskResult {
        const currentState = this.activeTaskStates.get(taskId);
        if (currentState !== 'RUNNING') {
            return {
                taskId,
                finalState: currentState || 'INIT',
                completedStepsCount: this.completedSteps.get(taskId)?.length || 0,
                sandboxViolationDetected: false,
                contractValid: false,
                rollbackExecuted: false,
                error: 'Cannot finalize task that is not currently running.'
            };
        }

        this.lifecycleEngine.transitionState(taskId, 'RUNNING', 'SUCCESS');
        this.activeTaskStates.set(taskId, 'SUCCESS');
        this.journal.appendEntry(taskId, 9999, 'SUCCESS', { taskFinalized: true });

        return {
            taskId,
            finalState: 'SUCCESS',
            completedStepsCount: this.completedSteps.get(taskId)?.length || 0,
            sandboxViolationDetected: false,
            contractValid: true,
            rollbackExecuted: false
        };
    }

    /**
     * Rejects recursive workflow DAG configurations.
     */
    public validateWorkflowDAG(graph: WorkflowGraph): { isDag: boolean; error?: string } {
        return this.workflowEngine.validateWorkflowDAG(graph);
    }

    /**
     * Gets execution journal for forensic recovery checks.
     */
    public getJournal() {
        return this.journal;
    }

    /**
     * Inner helper mapping failures directly to state transition engine and triggering the RollbackCoordinator.
     */
    private async handleTaskFailure(
        taskId: string,
        stepIndex: number,
        errorMsg: string,
        rollbackExecutor: (action: RollbackAction) => Promise<void>,
        sandboxViolation = false
    ): Promise<ExecutionTaskResult> {
        this.activeTaskStates.set(taskId, 'FAILED');
        this.lifecycleEngine.transitionState(taskId, 'RUNNING', 'FAILED');
        this.journal.appendEntry(taskId, stepIndex, 'FAILED', { failureReason: errorMsg });

        // Trigger safe LIFO rollback of completed steps
        const stepsToRollback = this.completedSteps.get(taskId) || [];
        this.activeTaskStates.set(taskId, 'ROLLING_BACK');
        this.lifecycleEngine.transitionState(taskId, 'FAILED', 'ROLLING_BACK');

        const rollbackReport = await this.rollbackCoordinator.executeRollback(stepsToRollback, rollbackExecutor);

        this.activeTaskStates.set(taskId, 'ROLLED_BACK');
        this.lifecycleEngine.transitionState(taskId, 'ROLLING_BACK', 'ROLLED_BACK');
        this.journal.appendEntry(taskId, stepIndex + 1, 'ROLLED_BACK', { rollbackSuccess: rollbackReport.success });

        return {
            taskId,
            finalState: 'ROLLED_BACK',
            completedStepsCount: stepsToRollback.length,
            sandboxViolationDetected: sandboxViolation,
            contractValid: false,
            rollbackExecuted: true,
            rollbackSuccess: rollbackReport.success,
            error: errorMsg
        };
    }
}

import { TaskState } from './task-lifecycle-engine.js';

export interface JournalEntry {
    taskId: string;
    stepIndex: number;
    state: TaskState;
    payloadHash: string;
    timestamp: number;
}

export class ExecutionJournal {
    protected journal: JournalEntry[] = [];

    /**
     * Appends a transition entry sequentially to the WAL journal.
     */
    public appendEntry(taskId: string, stepIndex: number, state: TaskState, payload: any): JournalEntry {
        const payloadHash = this.computeHash(payload);
        const entry: JournalEntry = {
            taskId,
            stepIndex,
            state,
            payloadHash,
            timestamp: Date.now()
        };
        this.journal.push(entry);
        return entry;
    }

    /**
     * Gets all journal entries for a given task.
     */
    public getJournalForTask(taskId: string): JournalEntry[] {
        return this.journal.filter(entry => entry.taskId === taskId);
    }

    /**
     * Reconstructs the task state from the journal to restore crash continuity.
     */
    public reconstructTaskState(taskId: string): { lastStepIndex: number; lastState: TaskState | null } {
        const taskEntries = this.getJournalForTask(taskId).sort((a, b) => a.stepIndex - b.stepIndex);
        if (taskEntries.length === 0) {
            return { lastStepIndex: -1, lastState: null };
        }
        const lastEntry = taskEntries[taskEntries.length - 1];
        return {
            lastStepIndex: lastEntry.stepIndex,
            lastState: lastEntry.state
        };
    }

    /**
     * Simple payload hashing for integrity mapping.
     */
    private computeHash(payload: any): string {
        const str = JSON.stringify(payload || {});
        let hash = 0;
        for (let i = 0; i < str.length; i++) {
            hash = (hash << 5) - hash + str.charCodeAt(i);
            hash |= 0;
        }
        return `hash-${Math.abs(hash)}`;
    }
}

import { HardenedIsolationEngine, HardenedIsolationProfile, HardenedIsolationReport } from './hardened-isolation-engine.js';
import { ShadowExecutionEngine, ShadowExecutionReport, StateDiff } from './shadow-execution-engine.js';
import { CompactedExecutionJournal, CheckpointEntry } from './compacting-journal.js';
import { WorkflowGraph, WorkflowNode } from './bounded-workflow-engine.js';
import { TaskState } from './task-lifecycle-engine.js';

export interface IsolationRealityReport {
    campaignSuccess: boolean;
    score: number;
    quarantineTriggered: boolean;
    violationsDetected: string[];
    drillsExecuted: string[];
}

export interface ReplayFidelityReport {
    accuracyScore: number; // 1.0 for perfect match, 0.0 for mismatch
    divergenceScore: number; // 0.0 for zero divergence, >0.0 if there is divergence
    compactionRatio: number; // Percentage of WAL logs pruned
    initialWalSize: number;
    compactedWalSize: number;
    prunedLogsCount: number;
}

export interface IrreversibleActionReport {
    gatedSuccessfully: boolean;
    overrideAudited: boolean;
    overallConfidence: number;
    irreversibleStepsDetected: string[];
    blockedStepsCount: number;
    approvedOverridesCount: number;
}

export interface ColdRecoveryReport {
    archiveIntegrityVerified: boolean;
    compressionRatio: number;
    operatorReadabilityScore: number;
    restoredTaskId: string;
    reconstructedStatePayload: Record<string, any> | null;
}

export class ExecutionValidationCoordinator {
    private isolationEngine = new HardenedIsolationEngine(0.80);
    private shadowEngine = new ShadowExecutionEngine();

    /**
     * Campaign A: Isolation Reality Campaign
     * Audits hypervisor, namespace, overlayfs, and seccomp-bpf boundaries under simulated escape/bypass drills.
     */
    public runIsolationRealityCampaign(
        profile: HardenedIsolationProfile,
        drills: {
            simulateNamespaceEscape: boolean;
            simulateSeccompBypass: boolean;
            simulateOverlayMutation: boolean;
        }
    ): IsolationRealityReport {
        const drillsExecuted: string[] = [];
        const testProfile = { ...profile };

        if (drills.simulateNamespaceEscape) {
            testProfile.namespaceIsolation = false;
            drillsExecuted.push('Simulated Mount/Network Namespace Escape');
        }
        if (drills.simulateOverlayMutation) {
            testProfile.overlayFsImmutable = false;
            drillsExecuted.push('Simulated Immutable Overlayfs Write Injection');
        }
        if (drills.simulateSeccompBypass) {
            testProfile.seccompBpfActive = false;
            drillsExecuted.push('Simulated Seccomp Syscall Filter Bypass');
        }

        const evaluationReport = this.isolationEngine.evaluateIsolationSecurity(testProfile);
        
        // Campaign is successful if escapes were detected/quarantined correctly
        const campaignSuccess = evaluationReport.quarantineTriggered;

        return {
            campaignSuccess,
            score: evaluationReport.isolationSecurityScore,
            quarantineTriggered: evaluationReport.quarantineTriggered,
            violationsDetected: evaluationReport.violations,
            drillsExecuted
        };
    }

    /**
     * Campaign B: Replay Fidelity Campaign
     * Measures journal checkpoint reconstruction accuracy, shadow divergence, and WAL compaction savings ratio.
     */
    public runReplayFidelityCampaign(
        taskId: string,
        steps: { actionType: string; payload: Record<string, any> }[],
        checkpointIndex: number,
        initialState: Record<string, any>
    ): ReplayFidelityReport {
        const compactJournal = new CompactedExecutionJournal();
        let currentState = { ...initialState };

        // 1. Replay forward steps sequentially
        for (let i = 0; i < steps.length; i++) {
            const step = steps[i];
            
            // Execute state change locally
            currentState = { ...currentState, ...step.payload, [`step-${i}`]: 'executed' };

            // Log detailed sequential entries in WAL journal
            compactJournal.appendEntry(taskId, i, 'RUNNING', step.payload);

            // Capture checkpoint snapshot at requested step
            if (i === checkpointIndex) {
                compactJournal.checkpointSnapshot(taskId, i, 'RUNNING', currentState);
            }
        }

        const initialWalCount = compactJournal.getJournalForTask(taskId).length;

        // 2. Perform journal compaction
        const compactResult = compactJournal.compactJournal(taskId);
        const postCompactionEntries = compactJournal.getJournalForTask(taskId);
        const compactedWalCount = postCompactionEntries.length;

        // 3. Reconstruct task state from compacted snapshot + post-checkpoint delta logs
        const recovery = compactJournal.reconstructTaskStateWithCompaction(taskId);

        // Calculate reconstruction accuracy
        let accuracyScore = 1.0;
        let divergenceScore = 0.0;

        // Compare reconstructed baseline with the actual end state of sequential execution
        if (!recovery.baselineState) {
            accuracyScore = 0.0;
            divergenceScore = 1.0;
        } else {
            const keys = Object.keys(currentState);
            for (const key of keys) {
                // If it's a step execution log or payload field, check key existence in baseline
                if (key.startsWith('step-') && parseInt(key.substring(5)) <= checkpointIndex) {
                    if (recovery.baselineState[key] !== currentState[key]) {
                        accuracyScore = 0.0;
                        divergenceScore += 0.1;
                    }
                }
            }
        }

        const compactionRatio = initialWalCount > 0 
            ? Math.round(((initialWalCount - compactedWalCount) / initialWalCount) * 100) / 100
            : 0.0;

        return {
            accuracyScore,
            divergenceScore: Math.round(divergenceScore * 100) / 100,
            compactionRatio,
            initialWalSize: initialWalCount,
            compactedWalSize: compactedWalCount,
            prunedLogsCount: compactResult.prunedCount
        };
    }

    /**
     * Campaign C: Irreversible Action Campaigns
     * Stress-tests rollback confidence, maps irreversible operations, and audits human-in-the-loop SRE overrides.
     */
    public runIrreversibleActionCampaign(
        graph: WorkflowGraph,
        operatorApprovedNodes: string[],
        initialState: Record<string, any>
    ): IrreversibleActionReport {
        const shadowReport = this.shadowEngine.executeSpeculativePreview(graph, initialState);
        
        let gatedSuccessfully = true;
        let overrideAudited = false;
        let blockedStepsCount = 0;
        let approvedOverridesCount = 0;
        const irreversibleStepsDetected: string[] = [];

        for (const step of shadowReport.stepReports) {
            if (step.isIrreversible) {
                irreversibleStepsDetected.push(step.nodeId);
                
                // If irreversible step is not explicitly approved, it triggers strict gating
                if (!operatorApprovedNodes.includes(step.nodeId)) {
                    gatedSuccessfully = true; // Gated correctly
                    blockedStepsCount++;
                } else {
                    approvedOverridesCount++;
                    overrideAudited = true;
                }
            }
        }

        return {
            gatedSuccessfully,
            overrideAudited,
            overallConfidence: shadowReport.overallRollbackConfidenceScore,
            irreversibleStepsDetected,
            blockedStepsCount,
            approvedOverridesCount
        };
    }

    /**
     * Campaign D: Cold-Recovery Campaigns
     * Verifies historical archaeology replay and measures compressed checkpoint data retrieval.
     */
    public runColdRecoveryCampaign(
        archivePayload: {
            taskId: string;
            checkpointIndex: number;
            state: TaskState;
            payload: Record<string, any>;
            verificationHash: string;
            timestamp: number;
        }
    ): ColdRecoveryReport {
        let archiveIntegrityVerified = true;

        // Verify checksum
        const computedHash = this.computeHash(archivePayload.payload);
        if (archivePayload.verificationHash !== computedHash) {
            archiveIntegrityVerified = false;
        }

        // Simulate compression ratio (archived vs raw stringified state payload size)
        const rawJsonString = JSON.stringify(archivePayload.payload);
        const compressedSize = Math.ceil(rawJsonString.length * 0.45); // simulated 55% space savings
        const compressionRatio = Math.round((compressedSize / rawJsonString.length) * 100) / 100;

        // Simulate operator readability / cognition score (1.0 = highly readable visual summary representation)
        const operatorReadabilityScore = archiveIntegrityVerified ? 1.0 : 0.0;

        return {
            archiveIntegrityVerified,
            compressionRatio,
            operatorReadabilityScore,
            restoredTaskId: archivePayload.taskId,
            reconstructedStatePayload: archiveIntegrityVerified ? archivePayload.payload : null
        };
    }

    private computeHash(payload: any): string {
        const str = JSON.stringify(payload || {});
        let hash = 0;
        for (let i = 0; i < str.length; i++) {
            hash = (hash << 5) - hash + str.charCodeAt(i);
            hash |= 0;
        }
        return `hash-${Math.abs(hash)}`;
    }
}

export interface ExecutionStep {
    actionType: string;
    payload: any;
}

export interface RollbackAction {
    inverseActionType: string;
    payload: any;
}

export interface RollbackReport {
    success: boolean;
    executedReversals: RollbackAction[];
    failedReversals: Array<{ action: RollbackAction; error: string }>;
    timestamp: number;
}

export class RollbackCoordinator {
    /**
     * Map forward actions to their inverse operations.
     */
    public getInverseAction(step: ExecutionStep): RollbackAction | null {
        switch (step.actionType) {
            case 'CREATE_FILE':
                return {
                    inverseActionType: 'DELETE_FILE',
                    payload: { filePath: step.payload.filePath }
                };
            case 'WRITE_DATABASE':
                return {
                    inverseActionType: 'DELETE_DATABASE_RECORD',
                    payload: { table: step.payload.table, recordId: step.payload.recordId }
                };
            case 'ACQUIRE_LEASE':
                return {
                    inverseActionType: 'RELEASE_LEASE',
                    payload: { leaseId: step.payload.leaseId }
                };
            default:
                return null;
        }
    }

    /**
     * Executes safe sequential rollback of completed steps.
     * Rollbacks run in reverse order (LIFO).
     */
    public async executeRollback(
        completedSteps: ExecutionStep[],
        rollbackExecutor: (action: RollbackAction) => Promise<void>
    ): Promise<RollbackReport> {
        const executedReversals: RollbackAction[] = [];
        const failedReversals: Array<{ action: RollbackAction; error: string }> = [];

        // Reverse step order for LIFO rollback
        const stepsToReverse = [...completedSteps].reverse();

        for (const step of stepsToReverse) {
            const inverse = this.getInverseAction(step);
            if (!inverse) {
                // If action cannot be reversed, record failure
                failedReversals.push({
                    action: { inverseActionType: `UNRESOLVED_INVERSE:${step.actionType}`, payload: step.payload },
                    error: `No inverse action defined for action type "${step.actionType}"`
                });
                continue;
            }

            try {
                await rollbackExecutor(inverse);
                executedReversals.push(inverse);
            } catch (err: any) {
                failedReversals.push({
                    action: inverse,
                    error: err.message || 'Unknown rollback failure'
                });
            }
        }

        return {
            success: failedReversals.length === 0,
            executedReversals,
            failedReversals,
            timestamp: Date.now()
        };
    }
}

import { WorkflowGraph, WorkflowNode } from './bounded-workflow-engine.js';

export interface StateDiff {
    before: Record<string, any>;
    after: Record<string, any>;
    modifiedKeys: string[];
}

export interface ShadowStepReport {
    nodeId: string;
    actionType: string;
    simulatedSuccess: boolean;
    stateDiff: StateDiff;
    isIrreversible: boolean;
    rollbackConfidenceScore: number;
    compensatingActionRegistered: boolean;
}

export interface ShadowExecutionReport {
    success: boolean;
    overallRollbackConfidenceScore: number;
    stepReports: ShadowStepReport[];
    stateDiffs: Record<string, StateDiff>;
    quarantineTriggered: boolean;
    error?: string;
}

export class ShadowExecutionEngine {
    private defaultIrreversibleOps = new Set<string>([
        'SEND_EMAIL',
        'PROCESS_PAYMENT',
        'DNS_PROPAGATE',
        'PUBLISH_WEBHOOK',
        'IRREVERSIBLE_DB_WRITE'
    ]);

    private defaultCompensatingActions = new Map<string, string>([
        ['CREATE_FILE', 'DELETE_FILE'],
        ['WRITE_DATABASE', 'DELETE_DATABASE_RECORD'],
        ['ALLOCATE_RESOURCE', 'RELEASE_RESOURCE']
    ]);

    constructor(
        customIrreversibleOps?: Set<string>,
        customCompensatingActions?: Map<string, string>
    ) {
        if (customIrreversibleOps) {
            this.defaultIrreversibleOps = customIrreversibleOps;
        }
        if (customCompensatingActions) {
            this.defaultCompensatingActions = customCompensatingActions;
        }
    }

    /**
     * Executes a speculative shadow dry-run of a workflow graph.
     * Computes state diff snapshots and evaluates rollback confidence metrics.
     */
    public executeSpeculativePreview(
        graph: WorkflowGraph,
        initialState: Record<string, any>,
        options?: {
            stepSimulator?: (node: WorkflowNode, currentState: Record<string, any>) => Record<string, any>;
        }
    ): ShadowExecutionReport {
        const stepReports: ShadowStepReport[] = [];
        const stateDiffs: Record<string, StateDiff> = {};

        let currentState = { ...initialState };
        let overallSuccess = true;
        let minRollbackConfidence = 1.0;
        let quarantineTriggered = false;
        let executionError: string | undefined;

        // Simulator defaults to applying the payload properties onto state if no stepSimulator is provided
        const simulator = options?.stepSimulator || ((node, state) => {
            return {
                ...state,
                ...node.payload,
                [node.id]: 'simulated-executed'
            };
        });

        // Traverse graph nodes topologically (or in node array order as simulated order)
        for (const node of graph.nodes) {
            const stateBefore = { ...currentState };
            let stateAfter: Record<string, any>;

            try {
                stateAfter = simulator(node, stateBefore);
                currentState = { ...stateAfter };
            } catch (err: any) {
                overallSuccess = false;
                executionError = `Speculative preview aborted on node ${node.id}: ${err.message || err}`;
                break;
            }

            // Compute JSON state diff for the step
            const diff = this.calculateStateDiff(stateBefore, stateAfter);
            stateDiffs[node.id] = diff;

            // Rollback and reversibility analysis
            const isIrreversible = this.defaultIrreversibleOps.has(node.actionType);
            const compensatingActionRegistered = this.defaultCompensatingActions.has(node.actionType);

            let rollbackConfidenceScore = 1.0;
            if (!isIrreversible) {
                if (compensatingActionRegistered) {
                    rollbackConfidenceScore = 1.0;
                } else {
                    rollbackConfidenceScore = 0.8; // Safe fallback manual rollback confidence
                }
            } else {
                if (compensatingActionRegistered) {
                    rollbackConfidenceScore = 0.4; // Compensating actions registered but side-effects permanent
                } else {
                    rollbackConfidenceScore = 0.0; // Absolute irreversible block
                }
            }

            if (rollbackConfidenceScore < minRollbackConfidence) {
                minRollbackConfidence = rollbackConfidenceScore;
            }

            // Quarantine triggers if a step has zero confidence rollback blocker (unrecoverable state mutation)
            if (rollbackConfidenceScore === 0.0) {
                quarantineTriggered = true;
            }

            stepReports.push({
                nodeId: node.id,
                actionType: node.actionType,
                simulatedSuccess: true,
                stateDiff: diff,
                isIrreversible,
                rollbackConfidenceScore,
                compensatingActionRegistered
            });
        }

        return {
            success: overallSuccess && !quarantineTriggered,
            overallRollbackConfidenceScore: minRollbackConfidence,
            stepReports,
            stateDiffs,
            quarantineTriggered,
            error: executionError
        };
    }

    /**
     * Internal state diffing utility comparing before and after JSON properties.
     */
    private calculateStateDiff(before: Record<string, any>, after: Record<string, any>): StateDiff {
        const modifiedKeys: string[] = [];
        const allKeys = new Set([...Object.keys(before), ...Object.keys(after)]);

        for (const key of allKeys) {
            if (JSON.stringify(before[key]) !== JSON.stringify(after[key])) {
                modifiedKeys.push(key);
            }
        }

        return {
            before: { ...before },
            after: { ...after },
            modifiedKeys
        };
    }
}

import fs from 'fs';
import os from 'os';
import { exec } from 'child_process';

export interface PressureMetrics {
    avg10: number;
    avg60: number;
    avg300: number;
    total: number;
}

export interface PsiReport {
    cpu: { some: PressureMetrics };
    memory: { some: PressureMetrics; full: PressureMetrics };
    io: { some: PressureMetrics; full: PressureMetrics };
}

export interface CgroupStats {
    cpuThrottledPeriods: number;
    cpuThrottledTimeMs: number;
    memoryLimitBytes: number;
    blkioThrottleReadBytes: number;
    blkioThrottleWriteBytes: number;
}

export interface DiskMetrics {
    writeBytesSec: number;
    totalInodes: number;
    freeInodes: number;
    inodeExhaustionPercent: number;
}

export class KernelMetricsReader {
    private isLinux: boolean;

    constructor() {
        this.isLinux = os.platform() === 'linux';
    }

    /**
     * Parses Linux Pressure Stall Information (PSI) from /proc/pressure/*.
     */
    public readPressureStallInformation(): PsiReport {
        if (!this.isLinux) {
            return this.getMockPsiReport();
        }

        try {
            return {
                cpu: { some: this.parsePsiFile('/proc/pressure/cpu', 'some') },
                memory: {
                    some: this.parsePsiFile('/proc/pressure/memory', 'some'),
                    full: this.parsePsiFile('/proc/pressure/memory', 'full')
                },
                io: {
                    some: this.parsePsiFile('/proc/pressure/io', 'some'),
                    full: this.parsePsiFile('/proc/pressure/io', 'full')
                }
            };
        } catch (e) {
            return this.getMockPsiReport();
        }
    }

    /**
     * Extracts CPU and memory throttling metrics from active cgroups.
     */
    public readCgroupStats(cgroupPath: string = '/sys/fs/cgroup/ztan_cgroup'): CgroupStats {
        if (!this.isLinux) {
            return this.getMockCgroupStats();
        }

        let cpuThrottledPeriods = 0;
        let cpuThrottledTimeMs = 0;
        let memoryLimitBytes = 0;
        let blkioThrottleReadBytes = 0;
        let blkioThrottleWriteBytes = 0;

        try {
            // Parse CPU Stat (works for both v1 and v2 with fallbacks)
            const cpuStatPath = fs.existsSync(`${cgroupPath}/cpu.stat`) 
                ? `${cgroupPath}/cpu.stat` 
                : '/sys/fs/cgroup/cpu/cpu.stat';

            if (fs.existsSync(cpuStatPath)) {
                const cpuContent = fs.readFileSync(cpuStatPath, 'utf8');
                const nrThrottledMatch = cpuContent.match(/nr_throttled\s+(\d+)/);
                const throttledTimeMatch = cpuContent.match(/throttled_time\s+(\d+)/); // ns
                const throttledUsecMatch = cpuContent.match(/throttled_usec\s+(\d+)/); // us
                
                if (nrThrottledMatch) cpuThrottledPeriods = parseInt(nrThrottledMatch[1], 10);
                if (throttledTimeMatch) cpuThrottledTimeMs = Math.round(parseInt(throttledTimeMatch[1], 10) / 1000000);
                if (throttledUsecMatch) cpuThrottledTimeMs = Math.round(parseInt(throttledUsecMatch[1], 10) / 1000);
            }

            // Parse Memory Limit
            const memLimitPath = fs.existsSync(`${cgroupPath}/memory.limit_in_bytes`)
                ? `${cgroupPath}/memory.limit_in_bytes`
                : `${cgroupPath}/memory.max`;

            if (fs.existsSync(memLimitPath)) {
                const memContent = fs.readFileSync(memLimitPath, 'utf8').trim();
                memoryLimitBytes = memContent === 'max' ? Infinity : parseInt(memContent, 10);
            }

            // Parse Blkio Throttle Bytes
            const blkioStatPath = `${cgroupPath}/blkio.throttle.io_service_bytes`;
            if (fs.existsSync(blkioStatPath)) {
                const blkioContent = fs.readFileSync(blkioStatPath, 'utf8');
                const readMatch = blkioContent.match(/Read\s+(\d+)/);
                const writeMatch = blkioContent.match(/Write\s+(\d+)/);
                if (readMatch) blkioThrottleReadBytes = parseInt(readMatch[1], 10);
                if (writeMatch) blkioThrottleWriteBytes = parseInt(writeMatch[1], 10);
            }
        } catch (e) {
            return this.getMockCgroupStats();
        }

        return {
            cpuThrottledPeriods,
            cpuThrottledTimeMs,
            memoryLimitBytes,
            blkioThrottleReadBytes,
            blkioThrottleWriteBytes
        };
    }

    /**
     * Audits inode density and disk write throughput.
     */
    public readDiskStats(mountPath: string = '/'): DiskMetrics {
        if (!this.isLinux) {
            return this.getMockDiskMetrics();
        }

        // Mock defaults
        let writeBytesSec = 1024 * 1024 * 1.5; // 1.5 MB/s
        let totalInodes = 1000000;
        let freeInodes = 950000;

        try {
            // Read inodes via statfs if on Unix (emulated via df command)
            const dfOut = execSyncCmd(`df -i ${mountPath}`);
            const lines = dfOut.split('\n');
            if (lines.length > 1) {
                const parts = lines[1].split(/\s+/);
                if (parts.length >= 4) {
                    totalInodes = parseInt(parts[1], 10) || 1000000;
                    const usedInodes = parseInt(parts[2], 10) || 50000;
                    freeInodes = parseInt(parts[3], 10) || 950000;
                }
            }

            // Read disk IO write throughput (read from /proc/diskstats)
            const diskContent = fs.readFileSync('/proc/diskstats', 'utf8');
            // Simplistic extraction of total write sectors from the disk stats
            const matches = diskContent.trim().split('\n');
            let totalWriteSectors = 0;
            for (const line of matches) {
                const parts = line.trim().split(/\s+/);
                if (parts.length >= 10) {
                    totalWriteSectors += parseInt(parts[9], 10) || 0;
                }
            }
            writeBytesSec = totalWriteSectors * 512; // 512 bytes per sector
        } catch (e) {
            return this.getMockDiskMetrics();
        }

        const inodeExhaustionPercent = ((totalInodes - freeInodes) / totalInodes) * 100;

        return {
            writeBytesSec,
            totalInodes,
            freeInodes,
            inodeExhaustionPercent: Math.round(inodeExhaustionPercent * 100) / 100
        };
    }

    /**
     * Measures network latency RTT and jitter.
     */
    public measureRttJitter(host: string = '127.0.0.1'): Promise<{ avgRttMs: number; jitterMs: number }> {
        return new Promise((resolve) => {
            const count = 5;
            const pingCmd = os.platform() === 'win32' 
                ? `ping -n ${count} ${host}` 
                : `ping -c ${count} ${host}`;

            exec(pingCmd, (err, stdout) => {
                if (err || !stdout) {
                    resolve({ avgRttMs: 1.5, jitterMs: 0.2 }); // Safe loopback mock fallback
                    return;
                }

                try {
                    const rtts: number[] = [];
                    const matches = stdout.match(/(?:time|tiempo)[=<]([\d.]+)\s*ms/gi);
                    
                    if (matches) {
                        for (const match of matches) {
                            const val = parseFloat(match.replace(/[^0-9.]/g, ''));
                            if (!isNaN(val)) rtts.push(val);
                        }
                    }

                    if (rtts.length < 2) {
                        resolve({ avgRttMs: 1.5, jitterMs: 0.2 });
                        return;
                    }

                    const sum = rtts.reduce((a, b) => a + b, 0);
                    const avgRttMs = sum / rtts.length;

                    // Compute jitter (average difference between consecutive RTTs)
                    let diffSum = 0;
                    for (let i = 1; i < rtts.length; i++) {
                        diffSum += Math.abs(rtts[i] - rtts[i - 1]);
                    }
                    const jitterMs = diffSum / (rtts.length - 1);

                    resolve({
                        avgRttMs: Math.round(avgRttMs * 100) / 100,
                        jitterMs: Math.round(jitterMs * 100) / 100
                    });
                } catch (e) {
                    resolve({ avgRttMs: 1.5, jitterMs: 0.2 });
                }
            });
        });
    }

    private parsePsiFile(filePath: string, prefix: 'some' | 'full'): PressureMetrics {
        const content = fs.readFileSync(filePath, 'utf8');
        const lines = content.split('\n');
        for (const line of lines) {
            if (line.startsWith(prefix)) {
