                return {
                    avg10: avg10Match ? parseFloat(avg10Match[1]) : 0,
                    avg60: avg60Match ? parseFloat(avg60Match[1]) : 0,
                    avg300: avg300Match ? parseFloat(avg300Match[1]) : 0,
                    total: totalMatch ? parseInt(totalMatch[1], 10) : 0
