}

export interface ResurrectionReport {
    name: string;
    success: boolean;
    restoredState?: {
        name: string;
        type: string;
        activePayload: Record<string, any>;
        restoredAt: Date;
        sunsetAt: Date;
        requestContext: ResurrectionRequest;
    };
