    unmetPrerequisites: string[];
    complexityDebt?: ComplexityDebtReport;
    certificationReport?: EnvironmentCertificationReport;
    error?: string;
}

export class GovernanceResurrectionRegistry {
    private registry = new Map<string, RetiredSubsystemMetadata>();
    private activeResurrections = new Map<string, Record<string, any>>();
    private activeSystemComponents = new Set<string>();

    constructor(activeComponents?: string[]) {
        if (activeComponents) {
            activeComponents.forEach(c => this.activeSystemComponents.add(c));
        }
    }

    /**
     * Add an active component to the system topology
     */
    public addActiveComponent(name: string): void {
        this.activeSystemComponents.add(name);
    }

    /**
     * Records a retired item with its context, dependencies, and payload.
     */
    public registerRetirement(metadata: RetiredSubsystemMetadata): void {
        this.registry.set(metadata.name, metadata);
    }

    /**
     * Retrieves retired metadata.
     */
    public getRetirementMetadata(name: string): RetiredSubsystemMetadata | undefined {
        return this.registry.get(name);
    }

    /**
     * Estimates reintroduced complexity debt for a retired subsystem.
     */
    public calculateComplexityDebt(name: string): ComplexityDebtReport {
        const metadata = this.registry.get(name);
        if (!metadata) {
            return {
                subsystemName: name,
                governanceDebt: 0,
                telemetryDebt: 0,
                operatorCognitionDebt: 0,
                maintenanceBurden: 0
            };
        }

        const depCount = metadata.dependencies.length;
        const payloadFields = Object.keys(metadata.payload || {}).length;

        const governanceDebt = depCount * 25 + 20;
        const telemetryDebt = metadata.type === 'telemetry' ? 100 : 30;
        const operatorCognitionDebt = metadata.type === 'subsystem' ? 75 : 25;
        const maintenanceBurden = (depCount * 15) + (payloadFields * 10);

        return {
            subsystemName: name,
            governanceDebt,
            telemetryDebt,
            operatorCognitionDebt,
            maintenanceBurden
        };
    }

    /**
     * Performs a pre-flight environment certification check for a subsystem.
     */
    public certifyEnvironment(name: string, environmentConditions?: Record<string, any>): EnvironmentCertificationReport {
        const metadata = this.registry.get(name);
        const issues: string[] = [];

        if (!metadata) {
            return {
                subsystemName: name,
                certified: false,
                replayCompatibilityPassed: false,
                telemetryAvailabilityPassed: false,
                schemaCompatibilityPassed: false,
                dependencySurvivabilityPassed: false,
                compressionReversibilityPassed: false,
                explainabilityContinuityPassed: false,
                issues: [`Subsystem '${name}' is not in the resurrection registry.`]
            };
        }

        // Validate environment conditions
        const replayCompatibilityPassed = !(environmentConditions?.DISABLE_REPLAY_COMPATIBILITY === true);
        if (!replayCompatibilityPassed) issues.push('Replay archaeology compatibility check failed.');

        const telemetryAvailabilityPassed = !(environmentConditions?.MISSING_TELEMETRY_FIELDS === true);
        if (!telemetryAvailabilityPassed) issues.push('Required telemetry fields are unavailable.');

        const schemaCompatibilityPassed = !(environmentConditions?.INCOMPATIBLE_SCHEMAS === true);
        if (!schemaCompatibilityPassed) issues.push('Incompatible telemetry schema versions detected.');

        // Dependency survivability (checks if any dependencies are marked deprecated/broken in env)
        let dependencySurvivabilityPassed = true;
        if (environmentConditions?.DEPRECATED_DEPENDENCIES) {
            const deprecatedDeps = new Set<string>(environmentConditions.DEPRECATED_DEPENDENCIES);
            for (const dep of metadata.dependencies) {
                if (deprecatedDeps.has(dep)) {
                    dependencySurvivabilityPassed = false;
                    issues.push(`Dependency '${dep}' is deprecated in the current environment.`);
                }
            }
        }

        const compressionReversibilityPassed = !(environmentConditions?.CORRUPTED_COMPRESSION_ENGINE === true);
        if (!compressionReversibilityPassed) issues.push('Compression reversibility audit failed.');

        const explainabilityContinuityPassed = !(environmentConditions?.EXPLAINABILITY_GAP === true);
        if (!explainabilityContinuityPassed) issues.push('Explainability continuity gap detected.');

        const certified = 
            replayCompatibilityPassed && 
            telemetryAvailabilityPassed && 
            schemaCompatibilityPassed && 
            dependencySurvivabilityPassed && 
            compressionReversibilityPassed && 
            explainabilityContinuityPassed;

        return {
            subsystemName: name,
            certified,
            replayCompatibilityPassed,
            telemetryAvailabilityPassed,
            schemaCompatibilityPassed,
            dependencySurvivabilityPassed,
            compressionReversibilityPassed,
            explainabilityContinuityPassed,
            issues
        };
    }

    /**
     * Validates dependencies and prerequisites under friction-based gates,
     * calculates complexity debt, certifies environment, and restores the archived state.
     */
    public resurrectSubsystem(
        name: string, 
        request: ResurrectionRequest,
        environmentConditions?: Record<string, any>
    ): ResurrectionReport {
        const metadata = this.registry.get(name);
        if (!metadata) {
            return {
                name,
                success: false,
                unresolvedDependencies: [],
                unmetPrerequisites: [],
                error: `Subsystem '${name}' is not registered as retired.`
            };
        }

        // 1. Enforce Structured Resurrection Classification Friction Gates
        if (!request.restorationReason || request.restorationReason.trim().length < 15) {
            return {
                name,
                success: false,
                unresolvedDependencies: [],
                unmetPrerequisites: [],
                error: `Resurrection denied: restorationReason must be at least 15 characters to prevent psychologically "free" resurrections.`
            };
        }

        if (!request.reRetirementCondition || request.reRetirementCondition.trim().length < 15) {
            return {
                name,
                success: false,
                unresolvedDependencies: [],
                unmetPrerequisites: [],
                error: `Resurrection denied: reRetirementCondition must be at least 15 characters to enforce measurable removal triggers.`
            };
        }

        if (!request.rollbackPlan || request.rollbackPlan.trim().length < 15) {
            return {
                name,
                success: false,
                unresolvedDependencies: [],
                unmetPrerequisites: [],
                error: `Resurrection denied: rollbackPlan must be at least 15 characters to ensure clear reversibility plans.`
            };
        }

        if (request.telemetryDeltaEstimate < 0.0 || request.telemetryDeltaEstimate > 1.0) {
            return {
                name,
                success: false,
                unresolvedDependencies: [],
                unmetPrerequisites: [],
                error: `Resurrection denied: telemetryDeltaEstimate must be a valid probability float between 0.0 and 1.0.`
            };
        }

        if (request.sunsetDays <= 0 || request.sunsetDays > 180) {
            return {
                name,
                success: false,
                unresolvedDependencies: [],
                unmetPrerequisites: [],
                error: `Resurrection denied: sunsetDays must be greater than 0 and at most 180 days to prevent infinite complexity drift.`
            };
        }

        // 2. Perform Environment Certification Pre-flight Check
        const certReport = this.certifyEnvironment(name, environmentConditions);
        if (!certReport.certified) {
            return {
                name,
                success: false,
                unresolvedDependencies: [],
                unmetPrerequisites: [],
                certificationReport: certReport,
                error: `Resurrection denied: Environment compatibility certification failed: ${certReport.issues.join('; ')}`
            };
        }

        const unresolvedDependencies: string[] = [];
        const unmetPrerequisites: string[] = [];

        // 3. Validate dependencies
        for (const dep of metadata.dependencies) {
            if (!this.activeSystemComponents.has(dep) && !this.activeResurrections.has(dep)) {
                unresolvedDependencies.push(dep);
            }
        }

        // 4. Validate restoration prerequisites
        for (const prereq of metadata.restorationPrerequisites) {
            if (environmentConditions) {
                if (!environmentConditions[prereq]) {
                    unmetPrerequisites.push(prereq);
                }
            } else {
                unmetPrerequisites.push(prereq);
            }
        }

        const success = unresolvedDependencies.length === 0 && unmetPrerequisites.length === 0;
        const complexityDebt = this.calculateComplexityDebt(name);

        if (success) {
            this.activeResurrections.set(name, metadata.payload);
            this.activeSystemComponents.add(name);
            const sunsetAt = new Date();
            sunsetAt.setDate(sunsetAt.getDate() + request.sunsetDays);

            return {
                name,
                success: true,
                restoredState: {
                    name: metadata.name,
                    type: metadata.type,
                    activePayload: metadata.payload,
                    restoredAt: new Date(),
                    sunsetAt,
                    requestContext: request
                },
                unresolvedDependencies: [],
                unmetPrerequisites: [],
                complexityDebt,
                certificationReport: certReport
            };
        }

        return {
            name,
            success: false,
            unresolvedDependencies,
            unmetPrerequisites,
            complexityDebt,
            certificationReport: certReport,
            error: `Failed dependency or prerequisite validation for resurrection.`
        };
    }

    /**
     * Checks if a subsystem is currently resurrected.
     */
    public isResurrected(name: string): boolean {
        return this.activeResurrections.has(name);
    }

    /**
     * Gets the payload of a resurrected subsystem.
     */
    public getResurrectedPayload(name: string): Record<string, any> | undefined {
        return this.activeResurrections.get(name);
    }
}

import { PrismaClient } from '@prisma/client';

/**
 * ─── ZTAN Database Lock Contention Recorder ──────────────────────────────────
 * Samples storage transaction latencies and monitors database execution times
 * to record queue blockages and lock bottlenecks under load.
 * ────────────────────────────────────────────────────────────────────────────
 */

export class LockContentionRecorder {
    private prisma: PrismaClient;
    private lockWaitTimes: number[] = [];
    private blockInterval: NodeJS.Timeout | null = null;

    constructor() {
        this.prisma = new PrismaClient();
    }

    public start() {
        // Sample database transaction execution times every 500ms
        this.blockInterval = setInterval(async () => {
            const start = Date.now();
            try {
                // Execute a lightweight query to sample database lock round-trips
                await this.prisma.$executeRawUnsafe('SELECT 1;');
                const duration = Date.now() - start;
                this.lockWaitTimes.push(duration);
            } catch (e) {
                // Ignore temporary failures during injected chaos dropouts
            }
        }, 500);
    }

    public stop() {
        if (this.blockInterval) {
            clearInterval(this.blockInterval);
        }
        this.prisma.$disconnect();
    }

    public getStats() {
        const avgWait = this.lockWaitTimes.length > 0 
            ? this.lockWaitTimes.reduce((a, b) => a + b, 0) / this.lockWaitTimes.length 
            : 0;
        const maxWait = this.lockWaitTimes.length > 0 
            ? Math.max(...this.lockWaitTimes) 
            : 0;

        return {
            averageDbLatencyMs: parseFloat(avgWait.toFixed(2)),
            maxDbLatencyMs: maxWait,
            sampledTxCount: this.lockWaitTimes.length
        };
    }
}

/**
 * ─── ZTAN Operational Economics Model ─────────────────────────────────────────
 * Computes storage cost growth curves, replay execution computer charges,
 * and SRE operator labor cost projections to bound the system financially.
 * ────────────────────────────────────────────────────────────────────────────
 */

export interface CostProjection {
  durationDays: number;
  uncompressedBytes: number;
  compressedBytes: number;
  estimatedStorageCostUsd: number;
}

export interface OperationalCostReport {
  computeCostUsd: number;
  laborCostUsd: number;
  totalCostUsd: number;
}

export class OperationalEconomicsModel {
  private costPerGbMonth: number;
  private costPerComputeSecond: number;
  private operatorHourlyRate: number;

  constructor(
    costPerGbMonth: number = 0.023,       // Standard AWS S3 Standard rate per GB-month
    costPerComputeSecond: number = 0.000016, // AWS Lambda / VM CPU second rate
    operatorHourlyRate: number = 75.00     // Average SRE labor cost per hour
  ) {
    this.costPerGbMonth = costPerGbMonth;
    this.costPerComputeSecond = costPerComputeSecond;
    this.operatorHourlyRate = operatorHourlyRate;
  }

  /**
   * Projects storage footprint and associated costs over time.
   */
  public projectStorageCostGrowth(
    baseBytesPerDay: number,
    durationDays: number,
    compactionRatio: number // 0 to 1.0 (e.g. 0.8 means 80% compression/pruning)
  ): CostProjection {
    const uncompressedBytes = baseBytesPerDay * durationDays;
    const compressedBytes = Math.round(uncompressedBytes * (1.0 - compactionRatio));

    const compressedGb = compressedBytes / (1024 * 1024 * 1024);
    // Cost calculation: (GBs * rate) * (months of storage accum)
    const months = durationDays / 30;
    // Average storage size over the period is compressedGb / 2 assuming linear accumulation
    const avgGb = compressedGb / 2;
    const estimatedStorageCostUsd = Math.round((avgGb * this.costPerGbMonth * Math.max(1, months)) * 100) / 100;

    return {
      durationDays,
      uncompressedBytes,
      compressedBytes,
      estimatedStorageCostUsd
    };
  }

  /**
   * Estimates compute resource consumption and SRE labor costs for incidents.
   */
  public estimateComputeAndLaborCost(
    replayCount: number,
    avgReplayMs: number,
    mttrHours: number
  ): OperationalCostReport {
    const computeSeconds = (replayCount * avgReplayMs) / 1000;
    const computeCostUsd = Math.round((computeSeconds * this.costPerComputeSecond) * 100) / 100;
    const laborCostUsd = Math.round((mttrHours * this.operatorHourlyRate) * 100) / 100;

    return {
      computeCostUsd,
      laborCostUsd,
      totalCostUsd: Math.round((computeCostUsd + laborCostUsd) * 100) / 100
    };
  }

  /**
   * Generates a holistic telemetry ingestion and retention cost analysis report.
   */
  public generateEconomicReport(
    ingestionRateBytesSec: number,
    retentionDays: number = 30
  ): Record<string, any> {
    const dailyBytes = ingestionRateBytesSec * 24 * 60 * 60;
    const monthlyBytes = dailyBytes * 30;
    const monthlyGb = monthlyBytes / (1024 * 1024 * 1024);
    const estimatedMonthlyIngestionCost = Math.round((monthlyGb * this.costPerGbMonth) * 100) / 100;

    return {
      ingestionRateBytesSec,
      dailyVolumeMb: Math.round((dailyBytes / (1024 * 1024)) * 100) / 100,
      monthlyVolumeGb: Math.round(monthlyGb * 100) / 100,
      estimatedMonthlyCostUsd: estimatedMonthlyIngestionCost,
      retentionDays,
      criticalAlertOverheadCost: Math.round((this.operatorHourlyRate * 0.5) * 100) / 100 // half hour triage cost
    };
  }
}

import { PrismaClient } from '@prisma/client';

/**
 * ─── ZTAN Background Parity Snapshot Worker ──────────────────────────────────
 * Periodically audits outbox ledger chains and Write-Ahead Log logs in the
 * background to verify 100% hash chain alignment and zero lineage drift.
 * ────────────────────────────────────────────────────────────────────────────
 */

export class ParitySnapshotWorker {
    private prisma: PrismaClient;
    private checkInterval: NodeJS.Timeout | null = null;
    private auditHistory: { timestamp: Date; success: boolean; totalChecked: number }[] = [];

    constructor() {
        this.prisma = new PrismaClient();
    }

    public start() {
        // Run database parity and hash alignment audits every 1 second
        this.checkInterval = setInterval(async () => {
            const result = await this.auditParity();
            this.auditHistory.push({
                timestamp: new Date(),
                success: result.success,
                totalChecked: result.totalChecked
            });
        }, 1000);
    }

    public stop() {
        if (this.checkInterval) {
            clearInterval(this.checkInterval);
        }
        this.prisma.$disconnect();
    }

    public getHistory() {
        return this.auditHistory;
    }

    private async auditParity(): Promise<{ success: boolean; totalChecked: number }> {
        try {
            const blocks = await this.prisma.ztanLedgerBlock.findMany({
                orderBy: { id: 'asc' }
            });

            // Verify sequential Merkle hash links
            for (let i = 1; i < blocks.length; i++) {
                if (blocks[i].prevHash !== blocks[i - 1].hash) {
                    return { success: false, totalChecked: blocks.length };
                }
            }
            return { success: true, totalChecked: blocks.length };
        } catch (e) {
            return { success: false, totalChecked: 0 };
        }
    }
}

import { InstitutionalPilotRegistry, PilotMetadata } from '@packages/production-pilot';
import { OperatorValidator } from '../archaeology/operator-validator.js';

export interface PilotValidationResult {
    allowed: boolean;
    reason?: string;
}

export interface ObservableOverrideException {
    exceptionId: string;
    operator: string;
    targetInvariant: string;
    expiresAtIso: string;
    reason: string;
    signatureBase64: string;
}

export class PilotGate {
    private static ALLOWED_STEWARDS = new Set([
        'steward_omega',
        'steward_alpha',
        'steward_beta'
    ]);

    private static activeExceptions: ObservableOverrideException[] = [];

    /**
     * Enforces Layer 7 pilot execution limitations.
     */
    public static validateExecution(
        pilotId: string,
        currentConcurrency: number,
        currentDrift: number
    ): PilotValidationResult {
        const registryResult = InstitutionalPilotRegistry.validateExecutionAllowed(
            pilotId,
            currentConcurrency,
            currentDrift
        );

        if (!registryResult.allowed) {
            return {
                allowed: false,
                reason: registryResult.reason
            };
        }

        return { allowed: true };
    }

    /**
     * Authenticates a manual override request from a pilot operator.
     * Enforces that the operator is a registered steward and the signature format is NIST P-256 Base64.
     */
    public static validateStewardOverride(operator: string, signatureBase64: string): PilotValidationResult {
        if (!this.ALLOWED_STEWARDS.has(operator)) {
            return {
                allowed: false,
                reason: `OPERATOR_NOT_WHITELISTED: Operator "${operator}" is not an authorized ZTAN steward.`
            };
        }

        const isValidSignature = OperatorValidator.verifyP256SignatureLayout(signatureBase64);
        if (!isValidSignature) {
            return {
                allowed: false,
                reason: 'CRYPTOGRAPHIC_SIGNATURE_INVALID: Override signature is malformed or not NIST P-256 Base64.'
            };
        }

        return { allowed: true };
    }

    /**
     * Registers a cryptographically signed, observable emergency exception.
     */
    public static registerObservableException(exception: ObservableOverrideException): PilotValidationResult {
        const auth = this.validateStewardOverride(exception.operator, exception.signatureBase64);
        if (!auth.allowed) {
            return auth;
        }

        const now = Date.now();
        const expiresTime = new Date(exception.expiresAtIso).getTime();
        if (expiresTime <= now) {
            return { allowed: false, reason: 'EXPIRED_TIMESTAMP: Exception override timestamp has already expired.' };
        }

        this.activeExceptions.push(exception);
        console.log(`[ObservableException] Emergency override registered: ${exception.exceptionId} for Invariant "${exception.targetInvariant}" (Reason: "${exception.reason}")`);
        return { allowed: true };
    }

    /**
     * Checks if a valid, unexpired override is active for the target invariant.
     */
    public static checkObservableException(targetInvariant: string): boolean {
        const now = Date.now();
        // Prune expired on read
        this.activeExceptions = this.activeExceptions.filter(ex => new Date(ex.expiresAtIso).getTime() > now);

        return this.activeExceptions.some(ex => ex.targetInvariant === targetInvariant);
    }

    /**
     * Clears all active overrides.
     */
    public static clearActiveExceptions(): void {
        this.activeExceptions = [];
    }
}

import fs from 'fs';
import path from 'path';

/**
 * ─── ZTAN Soak Telemetry Report Generator ────────────────────────────────────
 * Compiles performance, GC, latency, and parity logs recorded during continuous
 * soak runs, exporting an auditable JSON summary to the local state storage.
 * ────────────────────────────────────────────────────────────────────────────
 */

export interface SoakReportData {
    durationMs: number;
    memoryStats: any;
    dbLatencyStats: any;
    parityHistory: any[];
    errors: string[];
    quarantineCount: number;
    chronologyAudit?: any;
}

export function generateSoakReport(workspaceRoot: string, data: SoakReportData): string {
    const reportDir = path.resolve(workspaceRoot, '.ztan');
    if (!fs.existsSync(reportDir)) {
        fs.mkdirSync(reportDir, { recursive: true });
    }

    const reportPath = path.join(reportDir, 'soak-report.json');
    const content = JSON.stringify({
        generatedAt: new Date().toISOString(),
        ...data
    }, null, 2);

    fs.writeFileSync(reportPath, content, 'utf8');
    console.log(`[Soak Reporter] Exported operational telemetry summary to: ${reportPath}`);
    return reportPath;
}

